155|  /**
156|   * TAXI DRILL-DOWN - Performance view of a specific unit
157|   */
158|  async getTaxiDrillDown(deviceId: string): Promise<TaxiDrillDownResponse> {
159|    const [device, lastHeartbeats, lastLocations, activePayroll, subscription] =
160|      await Promise.all([
161|        this.prisma.device.findUnique({
162|          where: { deviceId },
163|          include: {
164|            driver: {
165|              include: {
166|                subscriptions: { orderBy: { createdAt: 'desc' }, take: 1 }
167|              }
168|            }
169|          }
170|        }),
171|        this.prisma.deviceHeartbeat.findMany({
172|          where: { deviceId }, orderBy: { timestamp: 'desc' }, take: 10
173|        }),
174|        this.prisma.driverLocation.findMany({
175|          where: { deviceId }, orderBy: { timestamp: 'desc' }, take: 5
176|        }),
177|        this.prisma.payrollPayment.findFirst({
178|          where: {
179|            driver: { devices: { some: { deviceId } } },
180|            status: 'PENDING',
181|            month: new Date().getMonth() + 1,
182|            year: new Date().getFullYear()
183|          }
184|        }),
185|        this.prisma.subscription.findFirst({
186|          where: { device: { deviceId }, status: 'ACTIVE' },
187|          orderBy: { dueDate: 'desc' }
188|        })
189|      ]);
190|
191|    if (!device) throw new NotFoundException(`Taxi ${deviceId} not found`);
192|
193|    const hoursOffline = device.lastHeartbeat
194|      ? (Date.now() - device.lastHeartbeat.getTime()) / 3600000 : 999;
195|
196|    const connectivityStatus: SemaphoreColor = 
197|      hoursOffline < 0.083 ? 'GREEN' : hoursOffline < 24 ? 'YELLOW' : 'RED';
198|
199|    const batteryLevel = device.batteryLevel ?? 0;
200|    const batteryStatus: SemaphoreColor = 
201|      batteryLevel >= 40 ? 'GREEN' : batteryLevel >= 15 ? 'YELLOW' : 'RED';
202|
203|    return {
204|      device: {
205|        id: device.id,
206|        deviceId: device.deviceId,
207|        taxiNumber: device.taxiNumber || 'S/N',
208|        city: device.city || 'Desconocida',
209|        appVersion: device.appVersion || 'v0.0.0',
210|        playerStatus: device.playerStatus || 'OFFLINE'
211|      },
212|      connectivity: {
213|        status: connectivityStatus,
214|        lastHeartbeat: device.lastHeartbeat,
215|        hoursOffline: Math.round(hoursOffline * 10) / 10
216|      },
217|      battery: {
218|        current: batteryLevel,
219|        status: batteryStatus,
220|        history: lastHeartbeats.map(h => ({ ts: h.timestamp, level: h.batteryLevel }))
221|      },
222|      gps: {
223|        lastLat: device.lastLat,
224|        lastLng: device.lastLng,
225|        lastKnownLocations: lastLocations,
226|        googleMapsUrl: lastLocations[0]
227|          ? `https://maps.google.com/?q=${lastLocations[0].latitude},${lastLocations[0].longitude}`
228|          : null
229|      },
230|      financials: {
231|        subscriptionStatus: subscription?.status || 'MISSING',
232|        subscriptionEnd: subscription?.dueDate,
233|        daysUntilExpiry: subscription?.dueDate
234|          ? Math.ceil((subscription.dueDate.getTime() - Date.now()) / 86400000)
235|          : 0,
236|        payrollPending: activePayroll
237|          ? { amount: activePayroll.amount, since: activePayroll.createdAt }
238|          : null
239|      },
240|      driver: {
241|        name: device.driver?.fullName || 'Sin Asignar',
242|        phone: device.driver?.phone || 'N/A',
243|        subscriptionPaid: device.driver?.subscriptionPaid || false
244|      }
245|    };
