248|  /**
249|   * RECONCILIATION - Audit loop (SRE Optimized)
250|   * Process drivers in small chunks to prevent OOM on 512MB RAM.
251|   */
252|  async generateReconciliationReport(period: string) {
253|    const [year, month] = period.split('-').map(Number);
254|    const periodStart = new Date(year, month - 1, 1);
255|    const periodEnd   = new Date(year, month, 0, 23, 59, 59);
256|
257|    const drivers = await this.prisma.driver.findMany({
258|      include: {
259|        devices: true,
260|        campaigns: true,
261|        subscriptions: { where: { startDate: { lte: periodEnd }, dueDate: { gte: periodStart } } },
262|        payrollPayments: { where: { month, year } }
263|      }
264|    });
265|
266|    this.logger.log(`🧬 Auditing ${drivers.length} drivers for period ${period}...`);
267|    
268|    const results = [];
269|    // Sequential Batching: 5 drivers at a time to stay under RAM limits
270|    for (let i = 0; i < drivers.length; i += 5) {
271|      const chunk = drivers.slice(i, i + 5);
272|      const chunkResults = await Promise.all(chunk.map(async (driver) => {
273|        const device       = driver.devices[0];
274|        const subscription = driver.subscriptions[0];
275|
276|        // Optimized count query
277|        const deliveredImpressions = device ? await this.prisma.playbackEvent.count({
278|          where: { 
279|            deviceId: device.deviceId, 
280|            eventType: { in: ['play_confirm', 'END'] }, 
281|            timestamp: { gte: periodStart, lte: periodEnd } 
282|          }
283|        }) : 0;
284|
285|        const revenueAgg = await this.prisma.financialTransaction.aggregate({
286|          where: { 
287|            type: 'INCOMING', 
288|            status: 'COMPLETED', 
289|            category: 'PUBLICIDAD', 
290|            createdAt: { gte: periodStart, lte: periodEnd } 
291|          },
292|          _sum: { amount: true }
293|        });
294|
295|        const payrollDue  = driver.payrollPayments.reduce((a, p) => a + p.amount, 0);
296|        const payrollPaid = driver.payrollPayments.filter(p => p.status === 'PAID').reduce((a, p) => a + p.amount, 0);
297|        const revenueReceived = Number(revenueAgg._sum?.amount ?? 0);
298|        const revenueContracted = 1500; 
299|
300|        let discrepancyType = 'OK';
301|        let hasDiscrepancy  = false;
302|        
303|        if (subscription?.status !== 'ACTIVE') {
304|          discrepancyType = 'UNPAID_SUBSCRIPTION';
305|          hasDiscrepancy = true;
306|        } else if (deliveredImpressions < 10) { // Example: low delivery alert
307|           discrepancyType = 'LOW_DELIVERY';
308|           hasDiscrepancy = true;
309|        }
310|
311|        return this.prisma.reconciliationReport.upsert({
312|          where: { period_driverId: { period, driverId: driver.id } },
313|          create: {
314|            period, 
315|            driverId: driver.id, 
316|            deviceId: device?.id,
317|            subscriptionStatus: subscription?.status || 'MISSING',
318|            subscriptionDueDate: subscription?.dueDate,
319|            subscriptionAmount: subscription?.amount || 0,
320|            totalPlaybacks: deliveredImpressions,
321|            activeCampaigns: driver.campaigns?.length || 0, 
322|            revenueContracted, 
323|            revenueReceived,
324|            payrollDue: Number(payrollDue.toFixed(2)), 
325|            payrollPaid: Number(payrollPaid.toFixed(2)), 
326|            hasDiscrepancy, 
327|            discrepancyType, 
328|            discrepancyAmount: 0
329|          },
330|          update: {
331|            subscriptionStatus: subscription?.status || 'MISSING',
332|            totalPlaybacks: deliveredImpressions,
333|            hasDiscrepancy, 
334|            discrepancyType,
335|            revenueReceived,
336|            payrollDue: Number(payrollDue.toFixed(2)),
337|            payrollPaid: Number(payrollPaid.toFixed(2))
338|          }
339|        });
340|      }));
341|      results.push(...chunkResults);
342|      if (i % 25 === 0) this.logger.debug(`Reconciliation Progress: ${i}/${drivers.length}`);
343|    }
344|
345|    return { period, total: results.length };
346|  }
347|
348|  async getReconciliationReport(period: string) {
349|    return this.prisma.reconciliationReport.findMany({
350|      where: { period },
351|      include: {
352|        driver: {
353|          select: {
354|            fullName: true,
355|            phone: true,
356|            taxiPlate: true
357|          }
358|        }
359|      },
360|      orderBy: { hasDiscrepancy: 'desc' }
361|    });
362|  }
363|
364|  /**
365|   * Fleet health snapshot. Returns up to `take` devices ordered by most
366|   * recently seen (descending). Defaults to 500 to stay within the 512MB
367|   * RAM budget; callers can pass a smaller `take` for dashboards.
368|   */
369|  async getFleetHealth(take: number = 500) {
370|    const safeTake = Math.min(Math.max(1, Math.floor(take)), 500);
371|    const devices = await this.prisma.device.findMany({
372|      take: safeTake,
373|      orderBy: { lastSeen: { sort: 'desc', nulls: 'last' } },
374|      include: { driver: true }
375|    });
376|
377|    return devices.map(d => ({
378|      id: d.id,
379|      deviceId: d.deviceId,
380|      taxiNumber: d.taxiNumber,
381|      isOnline: d.isOnline,
382|      batteryLevel: d.batteryLevel || 0,
383|      driverName: d.driver?.fullName
384|    }));
385|  }
386|
387|  async getHotspots() {
388|    const locations = await this.prisma.driverLocation.findMany({
389|      take: 1000, orderBy: { timestamp: 'desc' },
390|      select: { latitude: true, longitude: true }
391|    });
392|    return locations.map(l => [l.latitude, l.longitude, 0.5]);
393|  }
