{"content": "1|import { Injectable, HttpException, HttpStatus, Logger } from '@nestjs/common';
2|import { PrismaService } from '../prisma/prisma.service';
3|import { NotificationsService } from '../notifications/notifications.service';
4|import * as jwt from 'jsonwebtoken';
5|import * as crypto from 'crypto';
6|import { BUSINESS_RULES } from '../../common/constants/business-rules';
7|
8|const mediaAssetSafeSelect = {
9|  id: true,
10|  campaignId: true,
11|  type: true,
12|  filename: true,
13|  url: true,
14|  fileSize: true,
15|  checksum: true,
