{"content": "1|import { Controller, Get, Param, Headers, HttpException, HttpStatus, Res } from '@nestjs/common';
2|import { SyncService } from './sync.service';
3|import { Public } from '../auth/decorators/public.decorator';
4|import { Response } from 'express';
5|
6|@Controller('sync')
7|export class SyncController {
8|  constructor(private readonly syncService: SyncService) {}
9|
10|  @Public()
11|  @Get(':deviceId')
12|  async getDeviceManifest(
13|    @Param('deviceId') deviceId: string,
14|    @Headers('if-none-match') ifNoneMatch: string,
15|    @Res({ passthrough: true }) res: Response,
16|  ) {
17|    if (!deviceId) {
18|      throw new HttpException('DEVICE_ID_REQUIRED', HttpStatus.BAD_REQUEST);
19|    }
20|    
21|    const manifest = await this.syncService.getDeviceManifest(deviceId);
22|    
23|    // Fast-path: Si el hash coincide, devolvemos 304 Not Modified instantáneo sin payload
24|    if (ifNoneMatch && ifNoneMatch === manifest.etag) {
25|      res.status(HttpStatus.NOT_MODIFIED).send();
26|      return;
27|    }
28|    
29|    res.setHeader('ETag', manifest.etag);
30|    res.setHeader('Cache-Control', 'public, max-age=0, must-revalidate');
31|    return manifest;
32|  }
33|}
