{"content": "1|import { Injectable, Logger } from '@nestjs/common';
2|import { PrismaService } from '../prisma/prisma.service';
3|
4|/**
5| * SRE v12.2.5 — TelemetryService with PoP Validation
6| *
7| * PROTOCOLO ANTI-OOM:
8| * 1. Batch size capped at MAX_BATCH_SIZE (500 points)
9| * 2. Uses for-loop instead of .map() chains to avoid triple memory allocation
10| * 3. Chunked inserts to prevent query string from exceeding PostgreSQL limits
11| *
12| * REVENUE SHIELD v12.2.5:
13| * - deviceId validated against registered devices (OPERATIVO status)
14| * - videoId validated against active campaigns
15| * - Playback events marked as verified/unverified
16| * - Rate limiting: max 60 playback events per minute per deviceId
17| * - Deduplication: ON CONFLICT for duplicate playback events
18| */
19|const MAX_BATCH_SIZE = 500;
20|const CHUNK_SIZE = 100;
21|const PLAYBACK_MAX_BATCH_SIZE = 200;
22|const PLAYBACK_RATE_LIMIT = 60; // events per minute per device
23|const PLAYBACK_RATE_WINDOW = 60_000; // 1 minute in ms
24|
25|@Injectable()
26|export class TelemetryService {
27|  private readonly logger = new Logger(TelemetryService.name);
28|  constructor(private readonly prisma: PrismaService) { }
29|
30|  // --- Rate Limiting (in-memory, per-instance) ---
31|  private playbackRateMap = new Map<string, number[]>();
32|
33|  checkPlaybackRateLimit(deviceId: string, additionalCount = 1): boolean {
34|    const now = Date.now();
35|    const windowStart = now - PLAYBACK_RATE_WINDOW;
36|    let timestamps = this.playbackRateMap.get(deviceId) || [];
37|
38|    // Prune timestamps outside the current window
39|    timestamps = timestamps.filter(t => t > windowStart);
40|
41|    if (timestamps.length + additionalCount > PLAYBACK_RATE_LIMIT) {
42|      return false;
43|    }
44|
45|    // Add the new event(s)
46|    for (let i = 0; i < additionalCount; i++) {
47|      timestamps.push(now + i);
48|    }
49|    this.playbackRateMap.set(deviceId, timestamps);
50|
51|    // Periodic cleanup of stale entries (prevent memory leak)
52|    if (this.playbackRateMap.size > 1000) {
53|      for (const [key, ts] of this.playbackRateMap.entries()) {
54|        if (ts.filter(t => t > windowStart).length === 0) {
55|          this.playbackRateMap.delete(key);
56|        }
57|      }
58|    }
59|
60|    return true;
61|  }
62|
63|  // --- Device Validation ---
64|  async validateDevice(deviceId: string): Promise<boolean> {
65|    try {
66|      const device = await this.prisma.device.findUnique({
67|        where: { deviceId },
68|        select: { status: true },
69|      });
70|      return device?.status === 'OPERATIVO';
71|    } catch {
72|      this.logger.error(`Error validating device ${deviceId}`);
73|      return false;
74|    }
75|  }
76|
77|  // --- Tablet Key Validation ---
78|  async validateTabletKey(deviceId: string, tabletKey: string): Promise<boolean> {
79|    try {
80|      const device = await this.prisma.device.findUnique({
81|        where: { deviceId },
82|        select: { authToken: true },
83|      });
84|      if (!device?.authToken) return false;
85|      return device.authToken === tabletKey;
86|    } catch {
87|      return false;
88|    }
89|  }
90|
91|  // --- Video Validation ---
92|  async validateVideo(videoId: string): Promise<boolean> {
93|    try {
94|      const video = await this.prisma.video.findUnique({
95|        where: { id: videoId },
96|        select: { campaignId: true },
97|      });
98|      if (!video) return false;
99|
100|      const campaign = await this.prisma.campaign.findUnique({
101|        where: { id: video.campaignId },
102|        select: { active: true, status: true },
103|      });
104|
105|      return campaign?.active === true && campaign?.status === 'ACTIVE';
106|    } catch {
107|      this.logger.error(`Error validating video ${videoId}`);
108|      return false;
109|    }
110|  }
111|
112|  // --- GPS Batch Sync ---
113|  async sync(data: any[]) {
114|    if (!data || data.length === 0) return;
115|
116|    const safeData = data.length > MAX_BATCH_SIZE
117|      ? data.slice(0, MAX_BATCH_SIZE)
118|      : data;
119|
120|    if (safeData.length < data.length) {
121|      this.logger.warn(
122|        `⚠️ [ANTI-OOM] Telemetry batch truncated: ${data.length} → ${safeData.length} points (max: ${MAX_BATCH_SIZE})`
123|      );
124|    }
125|
126|    try {
127|      let totalProcessed = 0;
128|
129|      for (let offset = 0; offset < safeData.length; offset += CHUNK_SIZE) {
130|        const chunk = safeData.slice(offset, offset + CHUNK_SIZE);
131|
132|        const values: string[] = [];
133|        const params: any[] = [];
134|
135|        for (let i = 0; i < chunk.length; i++) {
136|          const item = chunk[i];
137|          const base = i * 5;
138|          values.push(
139|            `(gen_random_uuid(), $${base + 1}, ST_SetSRID(ST_MakePoint($${base + 2}, $${base + 3}), 4326), $${base + 4}, $${base + 5})`
140|          );
141|          params.push(
142|            item.driverId,
143|            item.lng,
144|            item.lat,
145|            item.speed ?? 0,
146|            item.timestamp ? new Date(item.timestamp) : new Date(),
147|          );
148|        }
149|
150|        await this.prisma.$executeRawUnsafe(
151|          `INSERT INTO telemetry (id, driver_id, coords, speed, timestamp)
152|           VALUES ${values.join(', ')}
153|           ON CONFLICT (driver_id, timestamp) DO NOTHING`,
154|          ...params
155|        );
156|
157|        totalProcessed += chunk.length;
158|      }
159|
160|      this.logger.log(`✅ Batch sync completed: ${totalProcessed} points processed in ${Math.ceil(safeData.length / CHUNK_SIZE)} chunks.`);
161|    } catch (err) {
162|      this.logger.error(`Failed to batch sync telemetry: ${err.message}`);
163|    }
164|  }
165|
166|  // --- Single Playback Event ---
167|  async recordPlayback(data: {
168|    deviceId: string;
169|    videoId: string;
170|    eventType: 'START' | 'END' | 'ERROR';
171|    lat?: number;
172|    lng?: number;
173|    verified?: boolean;
174|    clientTimestamp?: string;
175|  }) {
176|    try {
177|      // Use raw SQL with ON CONFLICT for deduplication:
178|      // Same device + video + same-minute timestamp = duplicate
179|      const timestamp = data.clientTimestamp ? new Date(data.clientTimestamp) : new Date();
180|
181|      const result = await this.prisma.$executeRawUnsafe(
182|        `INSERT INTO playback_events (id, device_id, event_type, video_id, lat, lng, timestamp, is_simulated, verified)
183|         VALUES (gen_random_uuid(), $1, $2, $3, $4, $5,
184|                 date_trunc('minute', $6::timestamp),
185|                 false, $7)
186|         ON CONFLICT (device_id, video_id, timestamp)
187|         DO NOTHING`,
188|        data.deviceId,
189|        data.eventType,
190|        data.videoId,
191|        data.lat ?? null,
192|        data.lng ?? null,
193|        timestamp,
194|        data.verified ?? false,
195|      );
196|
197|      if (result === 0) {
198|        this.logger.warn(`⚠️ Duplicate playback rejected: device=${data.deviceId} video=${data.videoId}`);
199|        return { success: true, duplicate: true };
200|      }
201|
202|      return { success: true, verified: data.verified ?? false };
203|    } catch (err) {
204|      this.logger.error(`Failed to record playback event for device ${data.deviceId}`, err);
205|      // Fallback to Prisma ORM if raw SQL fails (e.g., dedup constraint not yet applied)
206|      try {
207|        return await this.prisma.playbackEvent.create({
208|          data: {
209|            deviceId: data.deviceId,
210|            videoId: data.videoId,
211|            eventType: data.eventType,
212|            lat: data.lat,
213|            lng: data.lng,
214|            timestamp: data.clientTimestamp ? new Date(data.clientTimestamp) : new Date(),
215|            verified: data.verified ?? false,
216|          },
217|        });
218|      } catch (fallbackErr) {
219|        this.logger.error(`Fallback playback insert also failed for device ${data.deviceId}`, fallbackErr);
220|        throw fallbackErr;
221|      }
222|    }
223|  }
224|
225|  // --- Bulk Playback Events ---
226|  async recordPlaybackBatch(events: any[]): Promise<{ processed: number; rejected: number }> {
227|    const safeEvents = events.length > PLAYBACK_MAX_BATCH_SIZE
228|      ? events.slice(0, PLAYBACK_MAX_BATCH_SIZE)
229|      : events;
230|
231|    if (safeEvents.length < events.length) {
232|      this.logger.warn(`⚠️ Playback batch truncated: ${events.length} → ${safeEvents.length} (max: ${PLAYBACK_MAX_BATCH_SIZE})`);
233|    }
234|
235|    let processed = 0;
236|    let rejected = 0;
237|
238|    // Process in chunks
239|    for (let offset = 0; offset < safeEvents.length; offset += CHUNK_SIZE) {
240|      const chunk = safeEvents.slice(offset, offset + CHUNK_SIZE);
241|
242|      const values: string[] = [];
243|      const params: any[] = [];
244|
245|      for (let i = 0; i < chunk.length; i++) {
246|        const event = chunk[i];
247|        const base = i * 7;
248|        const ts = event.clientTimestamp ? new Date(event.clientTimestamp) : new Date();
249|        values.push(
250|          `(gen_random_uuid(), $${base + 1}, $${base + 2}, $${base + 3}, $${base + 4}, $${base + 5}, date_trunc('minute', $${base + 6}::timestamp), false, $${base + 7})`
251|        );
252|        params.push(
253|          event.deviceId,
254|          event.eventType,
255|          event.videoId,
256|          event.lat ?? null,
257|          event.lng ?? null,
258|          ts,
259|          true, // verified = true for validated batch
260|        );
261|      }
262|
263|      try {
264|        const insertResult = await this.prisma.$executeRawUnsafe(
265|          `INSERT INTO playback_events (id, device_id, event_type, video_id, lat, lng, timestamp, is_simulated, verified)
266|           VALUES ${values.join(', ')}
267|           ON CONFLICT (device_id, video_id, timestamp)
268|           DO NOTHING`,
269|          ...params
270|        );
271|        processed += chunk.length;
272|        rejected += chunk.length - insertResult;
273|      } catch (err) {
274|        this.logger.error(`Batch playback chunk failed at offset ${offset}: ${err.message}`);
275|        // Fallback: insert individually via Prisma ORM
276|        for (const event of chunk) {
277|          try {
278|            await this.prisma.playbackEvent.create({
279|              data: {
280|                deviceId: event.deviceId,
281|                videoId: event.videoId,
282|                eventType: event.eventType,
283|                lat: event.lat,
284|                lng: event.lng,
285|                timestamp: event.clientTimestamp ? new Date(event.clientTimestamp) : new Date(),
286|                verified: true,
287|              },
288|            });
289|            processed++;
290|          } catch {
291|            rejected++;
292|          }
293|        }
294|      }
295|    }
296|
297|    this.logger.log(`✅ Playback batch: ${processed} processed, ${rejected} rejected (duplicates/errors)`);
298|    return { processed, rejected };
299|  }
