{"content": "1|import { Injectable, BadRequestException, Logger } from '@nestjs/common';
2|import { PrismaService } from '../prisma/prisma.service';
3|import { Prisma } from '@prisma/client';
4|
5|/**
6| * SRE v12.1.2 — WalletService (VULN #5 PATCHED)
7| *
8| * INTEGRIDAD FINANCIERA:
9| * - Suscripción Driver: RD$ 6,000
10| * - Pago por Ad: RD$ 500/mes
11| * - Toda inconsistencia dispara alerta al MonitoringController vía system_errors + notification
12| *
13| * VULN #5 PATCH (v12.1.2): Bloqueo Atómico de Billetera
14| * ────────────────────────────────────────────────────────
15| * Problema: withdraw() leía el balance y deducía en pasos separados.
16| * Dos peticiones concurrentes podían leer el mismo balance antes de que
17| * cualquiera decrementara, resultando en balance negativo (double-spend).
18| *
19| * Solución Arquitectónica:
20| * 1. SELECT FOR UPDATE → candado exclusivo a nivel de fila hasta COMMIT
21| * 2. UPDATE raw SQL → deducción atómica en una sola operación DB
22| * 3. ReadCommitted isolation → suficiente con SELECT FOR UPDATE;
23| *    Serializable sería overkill y causaría más fallos de transacción
24| * 4. Verificación post-deducción → safety net contra edge cases
25| *
26| * NOTA: El modelo Prisma `Wallet` (@map "wallets") existe pero no está
27| * poblado — el balance operativo vive en `Driver.walletBalance` (@map
28| * "wallet_balance" en tabla "drivers"). La migración al modelo `Wallet`
29| * como fuente autoritativa es scope P1 (VULN #7 divergence cleanup).
30| */
31|@Injectable()
32|export class WalletService {
33|  private readonly logger = new Logger(WalletService.name);
34|
35|  constructor(private readonly prisma: PrismaService) { }
36|
37|  async getBalance(driverId: string) {
38|    const activeAdsCount = await this.prisma.activeAd.count({
39|      where: { driverId, status: 'ACTIVE' },
40|    });
41|
42|    const cpaCount = await this.prisma.commission.count({
43|      where: { driverId, sourceType: 'ADVERTISER_SALE', status: 'APPROVED' },
44|    });
45|
46|    const referralCount = await this.prisma.driver.count({
47|      where: { referredBy: driverId, status: 'OPERATIVO' },
48|    });
49|
50|    const effectiveAds = Math.min(activeAdsCount, 15);
51|    const adsEarnings = effectiveAds * 500;
52|    const cpaEarnings = cpaCount * 500;
53|    const referralEarnings = referralCount * 500;
54|    const totalEarnings = adsEarnings + cpaEarnings + referralEarnings;
55|
56|    const driver = await this.prisma.driver.findUnique({
57|      where: { id: driverId },
58|      select: { walletBalance: true },
59|    });
60|
61|    return {
62|      driverId,
63|      adsEarnings,
64|      cpaEarnings,
65|      referralEarnings,
66|      totalEarnings,
67|      walletBalance: driver?.walletBalance || 0,
68|    };
69|  }
70|
71|  /**
72|   * VULN #5 PATCH (v12.1.2): Double-spend prevention.
73|   *
74|   * Flujo de transacción atómica:
75|   * ┌─────────────────────────────────────────────────────────────────┐
76|   * │ 1. SELECT wallet_balance FROM drivers WHERE id=? FOR UPDATE    │
77|   * │    → Candado exclusivo en la fila. Nadie puede leer/modificar  │
78|   * │      este balance hasta COMMIT o ROLLBACK.                     │
79|   * │                                                                │
80|   * │ 2. Verificar: balance >= amount → si no, InsufficientFunds    │
81|   * │                                                                │
82|   * │ 3. UPDATE drivers SET wallet_balance = wallet_balance - amount │
83|   * │    → Deducción atómica via raw SQL. No Prisma middleware.      │
84|   * │                                                                │
85|   * │ 4. SELECT wallet_balance (verify) → safety net post-deducción  │
86|   * │    Si balance < 0: restaurar amount + throw (impossible edge)  │
87|   * │                                                                │
88|   * │ 5. INSERT financial_transactions → registro del retiro         │
89|   * │                                                                │
90|   * │ COMMIT → libera el candado FOR UPDATE                          │
91|   * └─────────────────────────────────────────────────────────────────┘
92|   *
93|   * Isolation Level: ReadCommitted (sufficient with SELECT FOR UPDATE)
94|   * - Serializable sería overkill: causa más serialization failures
95|   * - SELECT FOR UPDATE ya garantiza exclusividad a nivel de fila
96|   * - ReadCommitted permite que otras transacciones lean filas no-lockeadas
97|   */
98|  async withdraw(driverId: string, amount: number) {
99|    if (amount <= 0) {
100|      throw new BadRequestException('Withdrawal amount must be positive');
101|    }
102|
103|    return this.prisma.$transaction(async (tx) => {
104|      // ── STEP 1: Candado exclusivo en la fila del Wallet ──
105|      // SELECT FOR UPDATE acquire un row-level exclusive lock.
106|      // Concurrent withdrawals on the SAME driver will block here
107|      // until this transaction commits or rolls back.
108|      const [driverRow] = await tx.$queryRaw<
109|        [{ id: string; wallet_balance: number; bank_account: string | null }]
110|      >`
111|        SELECT id, wallet_balance, bank_account
112|        FROM drivers
