26|  private hasBankAccountConfigured(bankAccount: unknown): boolean {
27|    if (!bankAccount || typeof bankAccount !== 'object' || Array.isArray(bankAccount)) {
28|      return false;
29|    }
30|
31|    const candidate = bankAccount as {
32|      banco?: unknown;
33|      cuenta?: unknown;
34|      cedula?: unknown;
35|      tipo?: unknown;
36|    };
37|
38|    return Boolean(candidate.banco && candidate.cuenta && candidate.cedula && candidate.tipo);
39|  }
40|
41|  /**
42|   * REGLA DE NEGOCIO 1: Validar acceso a la publicidad
43|   * [ACTUALIZADO]: Morosos reciben kill-switch 402; tablets sin conductor van a setup.
44|   */
45|  async checkTabletAccess(tabletId: string) {
46|    const device = await this.prisma.device.findUnique({
47|      where: { id: tabletId },
48|      include: {
49|        driver: {
50|          select: {
51|            id: true,
52|            fullName: true,
53|            phone: true,
54|            status: true,
55|            subscriptionPaid: true,
56|            subscriptionEnd: true,
57|            blockedAt: true,
58|          },
59|        },
60|      },
61|    });
62|
63|    if (!device || !device.driver) {
64|      return {
65|        access: false,
66|        action: 'SHOW_SETUP_SCREEN',
67|        message: 'Tablet no asignada a un chofer.',
68|        reason: 'NO_DRIVER_ASSIGNED',
69|      };
70|    }
71|
72|    const driver = device.driver;
73|    const now = Date.now();
74|    const subscriptionExpired = !!driver.subscriptionEnd && driver.subscriptionEnd.getTime() < now;
75|    const delinquent =
76|      !driver.subscriptionPaid ||
77|      subscriptionExpired ||
78|      driver.status === BUSINESS_RULES.STATUS.DRIVER.SUSPENDED ||
79|      driver.status === BUSINESS_RULES.STATUS.DRIVER.INITIAL;
80|
81|    if (delinquent) {
82|      return {
83|        access: false,
84|        action: 'KILL_SWITCH',
85|        httpStatus: 402,
86|        message: 'Conductor moroso. La PWA debe congelarse hasta regularizar el pago.',
87|        reason: subscriptionExpired ? 'SUBSCRIPTION_EXPIRED' : 'SUBSCRIPTION_PENDING',
88|        driverId: driver.id,
89|        driverStatus: driver.status,
90|        blockedAt: driver.blockedAt,
91|        subscriptionEnd: driver.subscriptionEnd,
92|      };
93|    }
94|
95|    return {
96|      access: true,
97|      action: 'PLAY_ADS',
98|      driverId: driver.id,
99|      driverName: driver.fullName,
100|    };
