104|   * REGLA DE NEGOCIO 2: Cálculo automático de pagos
105|   * RD$500 al mes por anuncio activo reproducido en su tablet.
106|   */
107|  async calculateMonthlyEarnings(driverId: string) {
108|    // FIX A-1: Contar solo las campañas asignadas al dispositivo del conductor, no globalmente
109|    const activeCampaignsCount = await this.prisma.deviceCampaign.count({
110|      where: {
111|        device: { driverId },
112|        campaign: { status: 'ACTIVE' },
113|      },
