135|  /**
136|   * Listar todos los choferes con su dispositivo y estado de suscripción
137|   */
138|  async findAll() {
139|    const [drivers, activeAdsCount] = await Promise.all([
140|      this.prisma.driver.findMany({
141|        include: {
142|          devices: {
143|            select: {
144|              id: true,
145|              deviceId: true,
146|              status: true,
147|              batteryLevel: true,
148|              appVersion: true,
149|              lastSeen: true,
150|            },
151|          },
