199|  /**
200|   * Registrar un nuevo chofer con su suscripción
201|   */
202|  async create(data: {
203|    fullName: string;
204|    cedula?: string;
205|    phone: string;
206|    taxiPlate?: string;
207|    licensePlate?: string;
208|    deviceId?: string;
209|    subscriptionPaid?: boolean;
210|    subscriptionEnd?: Date;
211|    password?: string;
212|    contractAccepted?: boolean;
213|    agreementVersion?: string;
214|    referredBy?: string;
215|  }) {
216|    const plainPassword = data.password?.trim() || `Tad-${data.phone.replace(/\D/g, '')}!`;
217|    // FIX B-2: Usar constante BCRYPT_ROUNDS en lugar de magic number
218|    const hashedPassword = await bcrypt.hash(plainPassword, BCRYPT_ROUNDS);
219|
220|    // SANEAMIENTO DE DATOS: Campos opcionales únicos deben ser null si están vacíos
221|    const sanitizedCedula = data.cedula?.trim() || null;
222|    const sanitizedTaxiPlate = (data.taxiPlate || data.licensePlate)?.trim() || null;
223|
224|    const driver = await this.prisma.driver.create({
225|      data: {
226|        fullName: data.fullName,
227|        cedula: sanitizedCedula,
228|        phone: data.phone,
229|        taxiPlate: sanitizedTaxiPlate,
230|        licensePlate: data.licensePlate,
231|        subscriptionPaid: data.subscriptionPaid ?? false,
232|        subscriptionEnd: data.subscriptionEnd,
233|        password: hashedPassword,
234|        insuranceAccepted: false, // Deprecated — TAD no longer offers insurance
235|        insuranceAcceptedAt: null,
236|        contractAccepted: data.contractAccepted ?? false,
237|        contractAcceptedAt: data.contractAccepted ? new Date() : null,
238|        agreementVersion: data.agreementVersion ?? '2.0',
239|        referredBy: data.referredBy || null,
240|        status: data.subscriptionPaid ? BUSINESS_RULES.STATUS.DRIVER.ACTIVE : BUSINESS_RULES.STATUS.DRIVER.INITIAL,
241|        onboardingStatus: data.contractAccepted ? BUSINESS_RULES.STATUS.DRIVER.ONBOARDING.READY : BUSINESS_RULES.STATUS.DRIVER.ONBOARDING.TOS_PENDING,
242|      },
243|      include: { devices: true },
244|    });
245|
246|    if (data.deviceId) {
247|      // FIX M-5: Loguear errores silenciados en lugar de descartarlos
248|      try {
249|        await this.prisma.device.update({
250|          where: { deviceId: data.deviceId },
251|          data: { driverId: driver.id },
252|        });
253|      } catch (err) {
254|        this.logger.warn(
255|          `[DRIVER_CREATE] No se pudo vincular deviceId ${data.deviceId} al conductor ${driver.id}: ${err.message}`,
256|        );
257|      }
258|    }
259|
260|    return {
261|      ...driver,
262|      generatedPassword: data.password ? null : plainPassword,
263|    };
264|  }
