266|  async login(phone: string, pass: string) {
267|    const user = await this.prisma.driver.findUnique({ where: { phone } });
268|    if (!user) {
269|      throw new UnauthorizedException('Chofer no encontrado con este teléfono');
270|    }
271|
272|    if (!user.password) {
273|      throw new UnauthorizedException('Debe configurar su contraseña contactando a soporte.');
274|    }
275|
276|    const isMatch = await bcrypt.compare(pass, user.password);
277|    if (!isMatch) {
278|      throw new UnauthorizedException('Contraseña incorrecta');
279|    }
280|
281|    const payload = {
282|      sub: user.id,
283|      phone: user.phone,
284|      role: 'DRIVER',
285|      app_metadata: {
286|        role: 'DRIVER',
