290|
291|    // FIX C-1: NO usar fallback hardcodeado. Si no hay secreto, el token no se puede firmar.
292|    const jwtSecret = this.configService.get<string>('SUPABASE_JWT_SECRET') || this.configService.get<string>('JWT_SECRET');
293|    if (!jwtSecret) {
