295|      throw new ForbiddenException('AUTH_CONFIG_MISSING_JWT_SECRET');
296|    }
297|
298|    const token = jwt.sign(payload, jwtSecret, { expiresIn: JWT_EXPIRY });
299|
300|    const device = await this.prisma.device.findFirst({ where: { driverId: user.id } });
301|
302|    return {
303|      access_token: token,
304|      driverId: user.id,
305|      name: user.fullName,
306|      role: 'DRIVER',
307|      entityId: user.id,
308|      deviceId: device?.deviceId || null,
