5|@Controller('telemetry')
6|export class TelemetryController {
7|  private readonly logger = new Logger(TelemetryController.name);
8|
9|  constructor(private readonly telemetryService: TelemetryService) { }
10|
11|  @Post('sync')
12|  @HttpCode(HttpStatus.CREATED)
13|  async sync(
14|    @Body() payload: { driverId: string; lat: number; lng: number; speed: number; timestamp?: string }[]
15|  ) {
16|    this.telemetryService.sync(payload).catch(err => this.logger.error(`Telemetry sync error: ${err.message}`));
17|    return { success: true };
18|  }
19|
20|  /**
21|   * REVENUE SHIELD v12.2.5: Playback endpoint with deviceId + timestamp validation.
22|   * - Validates deviceId against registered devices (must be OPERATIVO)
23|   * - Validates videoId against active campaigns
24|   * - Rate-limited per deviceId (60 events/min max)
25|   * - Optional X-Tablet-Key header for shared-secret verification
26|   */
27|  @Public()
28|  @Post('playback')
29|  @HttpCode(HttpStatus.CREATED)
30|  async recordPlayback(
31|    @Body() payload: { deviceId: string; videoId: string; eventType: 'START' | 'END' | 'ERROR'; lat?: number; lng?: number; clientTimestamp?: string },
32|    @Headers('x-tablet-key') tabletKey?: string,
33|  ) {
34|    // Rate limiting: check per-deviceId burst
35|    const rateLimitOk = this.telemetryService.checkPlaybackRateLimit(payload.deviceId);
36|    if (!rateLimitOk) {
37|      this.logger.warn(`⚠️ Rate limit exceeded for deviceId=${payload.deviceId}`);
38|      return { success: false, reason: 'RATE_LIMITED', message: 'Max 60 playback events per minute per device' };
39|    }
40|
41|    // Validate deviceId exists and is OPERATIVO
42|    const deviceValid = await this.telemetryService.validateDevice(payload.deviceId);
43|    if (!deviceValid) {
44|      this.logger.warn(`⚠️ Invalid or inactive deviceId=${payload.deviceId}`);
45|      return { success: false, reason: 'DEVICE_INVALID', message: 'Device not registered or not OPERATIVO' };
46|    }
47|
48|    // Optional: validate X-Tablet-Key if configured
49|    if (tabletKey) {
50|      const keyValid = await this.telemetryService.validateTabletKey(payload.deviceId, tabletKey);
51|      if (!keyValid) {
52|        this.logger.warn(`⚠️ Invalid tablet key for deviceId=${payload.deviceId}`);
53|        return { success: false, reason: 'TABLET_KEY_INVALID', message: 'X-Tablet-Key does not match registered device' };
54|      }
55|    }
56|
57|    // Validate videoId belongs to an active campaign
58|    const videoValid = await this.telemetryService.validateVideo(payload.videoId);
59|    if (!videoValid) {
60|      this.logger.warn(`⚠️ Invalid videoId=${payload.videoId} (no active campaign)`);
61|      return { success: false, reason: 'VIDEO_INVALID', message: 'Video not found or campaign not active' };
62|    }
63|
64|    // Timestamp validation: reject events older than 5 minutes or more than 1 minute in the future
65|    const ts = payload.clientTimestamp ? new Date(payload.clientTimestamp) : new Date();
66|    const now = new Date();
67|    const fiveMinAgo = new Date(now.getTime() - 5 * 60 * 1000);
68|    const oneMinFuture = new Date(now.getTime() + 60 * 1000);
69|    if (ts < fiveMinAgo || ts > oneMinFuture) {
70|      this.logger.warn(`⚠️ Timestamp out of window for deviceId=${payload.deviceId}: ${ts.toISOString()}`);
71|      return { success: false, reason: 'TIMESTAMP_INVALID', message: 'Event timestamp outside 5-minute acceptance window' };
72|    }
73|
74|    return this.telemetryService.recordPlayback({
75|      ...payload,
76|      verified: true,
77|      clientTimestamp: payload.clientTimestamp,
78|    });
79|  }
80|
81|  /**
82|   * Bulk playback endpoint for batch submissions from tablets.
83|   */
84|  @Public()
85|  @Post('playback-batch')
86|  @HttpCode(HttpStatus.CREATED)
87|  async recordPlaybackBatch(
88|    @Body() payload: { deviceId: string; videoId: string; eventType: 'START' | 'END' | 'ERROR'; lat?: number; lng?: number; clientTimestamp?: string }[],
89|    @Headers('x-tablet-key') tabletKey?: string,
90|  ) {
91|    if (!payload || payload.length === 0) {
92|      return { success: false, reason: 'EMPTY_PAYLOAD' };
93|    }
94|
95|    // Validate deviceId for the batch (all events assumed from same device)
96|    const deviceId = payload[0]?.deviceId;
97|    if (!deviceId) {
98|      return { success: false, reason: 'MISSING_DEVICE_ID' };
99|    }
100|
101|    const deviceValid = await this.telemetryService.validateDevice(deviceId);
102|    if (!deviceValid) {
103|      return { success: false, reason: 'DEVICE_INVALID', message: 'Device not registered or not OPERATIVO' };
104|    }
105|
106|    const videoIds = [...new Set(payload.map(e => e.videoId))];
107|    for (const videoId of videoIds) {
108|      const videoValid = await this.telemetryService.validateVideo(videoId);
109|      if (!videoValid) {
110|        this.logger.warn(`⚠️ Invalid videoId=${videoId} in batch`);
111|      }
112|    }
113|
114|    // Rate limit check for the batch
115|    const rateLimitOk = this.telemetryService.checkPlaybackRateLimit(deviceId, payload.length);
116|    if (!rateLimitOk) {
117|      return { success: false, reason: 'RATE_LIMITED', message: 'Max 60 playback events per minute per device' };
118|    }
119|
120|    const result = await this.telemetryService.recordPlaybackBatch(payload);
121|    return { success: true, processed: result.processed, rejected: result.rejected };
122|  }
