324|  async registerDeviceByAdmin(placa: string, nombreChofer: string, providedDeviceId?: string) {
325|    const crypto = require('crypto');
326|    let deviceId = providedDeviceId?.trim();
327|    if (!deviceId) {
328|      deviceId = 'TAD-' + crypto.randomUUID().split('-')[0].toUpperCase();
329|    }
330|    
331|    // 1. Verificar simultáneamente Dispositivo y Driver (por ID o por Teléfono generado)
332|    const phone = 'PH-' + deviceId;
333|    
334|    const [existingDevice, existingDriver] = await Promise.all([
335|      this.prisma.device.findUnique({
336|        where: { deviceId },
337|        include: { driver: true }
338|      }),
339|      this.prisma.driver.findFirst({
340|        where: { 
341|          OR: [
342|            { devices: { some: { deviceId } } },
343|            { phone }
344|          ]
345|        }
346|      })
347|    ]);
348|
349|    // Lógica de Unión (Upsert):
350|    // Si ya existe el dispositivo, lo actualizamos.
351|    if (existingDevice) {
352|      const updated = await this.prisma.device.update({
353|        where: { deviceId },
354|        data: {
355|          taxiNumber: placa,
356|          status: BUSINESS_RULES.STATUS.DEVICE.ACTIVE,
357|          driver: existingDevice.driver 
358|            ? {
359|                update: {
360|                  fullName: nombreChofer,
361|                  licensePlate: placa,
362|                  taxiNumber: placa,
363|                  status: BUSINESS_RULES.STATUS.DRIVER.ACTIVE
364|                }
365|              }
366|            : {
367|                // Si el dispositivo no tiene driver pero encontramos uno huérfano con este ID/Phone
368|                connectOrCreate: {
369|                  where: { phone },
370|                  create: {
371|                    fullName: nombreChofer,
372|                    phone: phone,
373|                    licensePlate: placa,
374|                    taxiNumber: placa,
375|                    status: BUSINESS_RULES.STATUS.DRIVER.ACTIVE
376|                  }
377|                }
378|              }
379|        }
380|      });
381|      return { success: true, device_id: updated.deviceId, driver_name: nombreChofer, linked: true };
382|    }
383|
384|    // 2. Si el dispositivo es nuevo pero el driver ya existía (ej: registro manual previo del chofer)
385|    if (existingDriver) {
386|      const device = await this.prisma.device.create({
387|        data: {
388|          deviceId,
389|          status: BUSINESS_RULES.STATUS.DEVICE.ACTIVE,
390|          taxiNumber: placa,
391|          driver: {
392|            connect: { id: existingDriver.id }
393|          }
394|        }
395|      });
396|      // Actualizar datos del driver vinculado
397|      await this.prisma.driver.update({
398|        where: { id: existingDriver.id },
399|        data: { fullName: nombreChofer, status: BUSINESS_RULES.STATUS.DRIVER.ACTIVE }
400|      });
401|      return { success: true, device_id: device.deviceId, driver_name: nombreChofer, linked_driver: true };
402|    }
403|
404|    // 3. Creación total desde cero
405|    const device = await this.prisma.device.create({
406|      data: {
407|        deviceId,
408|        status: BUSINESS_RULES.STATUS.DEVICE.ACTIVE,
409|        taxiNumber: placa,
410|        appVersion: '3.0.0',
411|        lastSeen: new Date(),
412|        driver: {
413|          create: {
414|            fullName: nombreChofer,
415|            phone: phone,
416|            licensePlate: placa,
417|            taxiNumber: placa,
418|            status: BUSINESS_RULES.STATUS.DRIVER.ACTIVE
419|          }
420|        }
421|      }
422|    });
423|
424|    return { 
425|      success: true, 
426|      device_id: device.deviceId,
427|      driver_name: nombreChofer,
428|      new_registration: true
429|    };
430|  }
