{"content": "1|import { ExecutionContext, Injectable, UnauthorizedException, CanActivate, Logger } from '@nestjs/common';
2|import { Reflector } from '@nestjs/core';
3|import { ConfigService } from '@nestjs/config';
4|import { IS_PUBLIC_KEY } from '../decorators/public.decorator';
5|import { SupabaseService } from '../../supabase/supabase.service';
6|import * as jwt from 'jsonwebtoken';
7|import { AuthUser } from '../auth.types';
8|
9|/**
10| * SUPABASE AUTH GUARD — Política "Deny-by-Default".
11| * Protege TODAS las rutas de la API globalmente (registrado en APP_GUARD).
12| *
13| * Flujo de validación (Híbrido):
14| * 1. Validación LOCAL usando SUPABASE_JWT_SECRET o JWT_SECRET (< 1ms).
15| * 2. Si falla, validamos contra la red de Supabase (> 200ms).
16| */
17|@Injectable()
18|export class SupabaseAuthGuard implements CanActivate {
19|  private readonly logger = new Logger(SupabaseAuthGuard.name);
20|  private readonly isDev: boolean;
21|  private readonly allowDevBypass: boolean;
22|
23|  // In-memory cache to avoid repeated network calls for the same token in a short window
24|  private static sessionCache = new Map<string, { user: AuthUser; expiry: number }>();
25|  private readonly CACHE_TTL_MS = 10000; // 10 seconds cache for same token
26|
27|  constructor(
28|    private reflector: Reflector,
29|    private supabaseService: SupabaseService,
30|    private configService: ConfigService,
31|  ) {
32|    this.isDev = process.env.NODE_ENV === 'development';
33|    this.allowDevBypass = this.isDev && process.env.ALLOW_DEV_BYPASS === 'true';
34|
35|    const hasSecret = !!(this.configService.get('SUPABASE_JWT_SECRET') || this.configService.get('JWT_SECRET'));
36|    if (!hasSecret) {
37|      this.logger.warn('⚠️ [SECURITY] No hay JWT_SECRET configurado. Solo funcionará Estrategia 2 (Red).');
38|    }
39|
40|    // Cleanup stale cache occasionally
41|    if (Math.random() > 0.95) {
42|      const now = Date.now();
43|      for (const [token, data] of SupabaseAuthGuard.sessionCache.entries()) {
44|        if (data.expiry < now) SupabaseAuthGuard.sessionCache.delete(token);
45|      }
46|    }
47|  }
48|
49|  async canActivate(context: ExecutionContext): Promise<boolean> {
50|    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
51|      context.getHandler(),
52|      context.getClass(),
53|    ]);
54|
55|    if (isPublic) return true;
56|
57|    const request = context.switchToHttp().getRequest();
58|    const authHeader = request.headers.authorization || request.headers.Authorization;
59|
60|    if (!authHeader || !authHeader.startsWith('Bearer ')) {
61|      this.logger.warn(`❌ [AUTH] Petición sin Header Authorization válido: ${request.url}`);
62|      throw new UnauthorizedException('Token de acceso no válido o ausente.');
63|    }
64|
65|    const token = authHeader.split(' ')[1];
66|
67|    // --- CACHE LOOKUP ---
68|    const cached = SupabaseAuthGuard.sessionCache.get(token);
69|    if (cached && cached.expiry > Date.now()) {
70|      request.user = cached.user;
71|      return true;
72|    }
73|
74|    const jwtSecret = this.configService.get<string>('SUPABASE_JWT_SECRET') || this.configService.get<string>('JWT_SECRET');
75|
76|    // --- ESTRATEGIA 1: Validación Local JWT ---
77|    if (jwtSecret) {
78|      try {
79|        const decodedToken = jwt.decode(token, { complete: true }) as any;
80|        const alg = decodedToken?.header?.alg || 'HS256';
81|        
82|        const isSymmetricSecret = !jwtSecret.includes('BEGIN PUBLIC KEY') && !jwtSecret.includes('BEGIN CERTIFICATE');
83|        const isAsymmetricAlg = alg.startsWith('RS') || alg.startsWith('ES') || alg.startsWith('PS');
84|
85|        if (isAsymmetricAlg && isSymmetricSecret) {
86|          // Skip Strategy 1: Cannot verify asymmetric token with a symmetric secret
87|          // Lo silenciamos para evitar spam en consola ya que es un flujo esperado (ES256 en lugar de HS256)
88|        } else {
89|          const payload = jwt.verify(token, jwtSecret, { 
90|            algorithms: [alg, 'HS256', 'HS384', 'HS512'] 
91|          }) as jwt.JwtPayload;
92|
93|          if (payload) {
94|            request.user = {
95|              id: payload.sub,
96|              email: payload.email,
97|              role: payload.app_metadata?.role || payload.role || 'GUEST',
98|              entityId: payload.app_metadata?.entityId || null,
99|            };
100|            
101|            // Cache sucessful validation
102|            SupabaseAuthGuard.sessionCache.set(token, { 
103|              user: request.user, 
104|              expiry: Date.now() + this.CACHE_TTL_MS 
105|            });
106|
107|            this.logger.verbose(`✅ [AUTH] ESTRATEGIA 1 OK (Local JWT): ${request.user.email}`);
108|            return true;
109|          }
110|        }
111|      } catch (err: unknown) {
112|        const errorMessage = err instanceof Error ? err.message : String(err);
113|        const errName = err instanceof Error ? err.name : '';
114|        
115|        if (errName === 'TokenExpiredError') {
116|          this.logger.warn(`🛑 [AUTH] TOKEN EXPIRADO: ${errorMessage}`);
117|          throw new UnauthorizedException('Tu sesión ha expirado.');
118|        }
119|
120|        // If it's a configuration issue with the secret/algorithm, we log it more clearly
121|        const isAlgError = errorMessage.toLowerCase().includes('algorithm');
122|        if (isAlgError) {
123|          this.logger.verbose(`[AUTH] Estrategia 1 falló (Algoritmo incompatible o Secret mal configurado: ${errorMessage}). Intentando Estrategia 2...`);
124|        } else {
125|          this.logger.verbose(`[AUTH] Estrategia 1 falló (${errorMessage}). Intentando Estrategia 2 (Red)...`);
126|        }
127|      }
128|    }
129|
130|    // --- ESTRATEGIA 2: Validación vía Supabase SDK (Red) ---
131|    try {
132|      const supabase = this.supabaseService.getClient();
133|      const { data, error } = await supabase.auth.getUser(token);
134|
135|      if (!error && data.user) {
136|        const decoded = jwt.decode(token) as jwt.JwtPayload;
137|        const roleFromMeta = 
138|          data.user.app_metadata?.role ||
139|          (decoded?.app_metadata?.role) ||
140|          (data.user as any).role ||
141|          decoded?.role ||
142|          'GUEST';
143|        const entityId =
