{"content": "1|import { Injectable, UnauthorizedException } from '@nestjs/common';
2|import { PassportStrategy } from '@nestjs/passport';
3|import { ExtractJwt, Strategy } from 'passport-jwt';
4|import { ConfigService } from '@nestjs/config';
5|
6|/**
7| * SUPABASE JWT STRATEGY — Validación LOCAL sin llamadas de red.
8| * Usa el SUPABASE_JWT_SECRET para verificar la firma del token matemáticamente.
9| * Esto elimina una llamada HTTP a Supabase por cada request del dashboard,
10| * reduciendo latencia y respetando los límites del Free Tier.
11| *
12| * Para obtener SUPABASE_JWT_SECRET:
13| * Supabase Dashboard > Project Settings > API > JWT Secret
14| */
15|@Injectable()
16|export class SupabaseStrategy extends PassportStrategy(Strategy, 'jwt') {
17|  constructor(private readonly configService: ConfigService) {
18|    const secret = configService.get<string>('SUPABASE_JWT_SECRET');
19|    
20|    // DIAGNÓSTICO DE SEGURIDAD PARA EL CTO:
21|    // Si el secreto empieza con 'sb_secret_', el usuario está usando la MANAGEMENT KEY 
22|    // en lugar del JWT SECRET de firma. Esto causará 401 en todas las validaciones.
23|    if (secret && secret.startsWith('sb_secret_')) {
24|      console.warn('🚨 ALERTA ARQUITECTO: El SUPABASE_JWT_SECRET parece ser una llave de gestión (sb_secret_). No funcionará para validar tokens de usuario. Reemplázalo con el "JWT Secret" de Settings > API de Supabase.');
25|    }
26|
27|    super({
28|      jwtFromRequest: ExtractJwt.fromExtractors([
29|        (request: any) => {
30|          let data = request?.headers?.authorization;
31|          if (!data) return null;
32|          // Limpia la cadena: quita "Bearer ", "bearer ", espacios extra y comillas
33|          data = data.replace(/bearer\s+/i, '').replace(/['"]/g, '').trim();
34|          return data;
35|        },
36|      ]),
37|      ignoreExpiration: false,
38|      secretOrKey: secret || configService.get<string>('JWT_SECRET') || 'tad-default-secret-change-me',
39|    });
40|  }
41|
42|  async validate(payload: any) {
43|    if (!payload || !payload.sub) {
44|      throw new UnauthorizedException('Token inválido o expirado.');
45|    }
46|
47|    // El payload de Supabase incluye: app_metadata con nuestro entityId y role
48|    const appMeta = payload.app_metadata || {};
49|    
50|    return {
51|      id: payload.sub,
52|      email: payload.email,
53|      role: appMeta.role || payload.role || 'ADMIN',
54|      entityId: appMeta.entityId || null,
55|    };
56|  }
57|}
