{"content": "1|import { Injectable, UnauthorizedException } from '@nestjs/common';
2|import { PassportStrategy } from '@nestjs/passport';
3|import { ExtractJwt, Strategy } from 'passport-jwt';
4|import { ConfigService } from '@nestjs/config';
5|import { SupabaseService } from '../../supabase/supabase.service';
6|
7|@Injectable()
8|export class JwtStrategy extends PassportStrategy(Strategy) {
9|  constructor(
10|    configService: ConfigService,
11|    private readonly supabaseService: SupabaseService,
12|  ) {
13|    super({
14|      jwtFromRequest: ExtractJwt.fromExtractors([
15|        (request: any) => {
16|          let data = request?.headers?.authorization;
17|          if (!data) return null;
18|          data = data.replace(/bearer\s+/i, '').replace(/['"]/g, '').trim();
19|          return data;
20|        },
21|      ]),
22|      ignoreExpiration: false,
23|      // We still need a secret for the base Strategy to not error, 
24|      // but we will do the real verification in validate() using Supabase.
25|      secretOrKey: configService.get<string>('JWT_SECRET') || 'tad-default-secret-change-me-in-production',
26|      passReqToCallback: true,
27|    });
28|  }
29|
30|  async validate(req: any, payload: any) {
31|    let token = req.headers.authorization;
32|    if (!token) throw new UnauthorizedException('No token provided');
33|    token = token.replace(/bearer\s+/i, '').replace(/['"]/g, '').trim();
34|
35|
36|    const supabase = this.supabaseService.getClient();
37|    const { data: { user }, error } = await supabase.auth.getUser(token);
38|
39|    if (error || !user) {
40|      throw new UnauthorizedException('Sesión inválida o expirada en Supabase');
41|    }
42|
43|    const appMeta = user.app_metadata || {};
44|
45|    return {
46|      id: user.id,
47|      email: user.email,
48|      role: appMeta.role || 'ADMIN',
49|      entityId: appMeta.entityId || null,
50|    };
51|  }
