{"content": "1|import { Injectable, CanActivate, ExecutionContext, HttpException, HttpStatus } from '@nestjs/common';
2|import { PrismaService } from '../../prisma/prisma.service';
3|import { Request } from 'express';
4|
5|/**
6| * REVENUE SHIELD v12.2.5: Subscription Guard
7| *
8| * Verifies that the device's associated driver has an active, paid subscription.
9| * Applied to tablet-facing endpoints (sync, playlist) to enforce the kill-switch.
10| *
11| * Returns HTTP 402 if:
12| *  - Driver.subscriptionPaid === false
13| *  - Driver.subscriptionEnd < now (subscription expired)
14| *
15| * Grace period: If the device is offline (no heartbeat in >24h), allow 48h
16| * of continued playback after subscription expiry, aligned with JWT expiry policy.
17| */
18|@Injectable()
19|export class SubscriptionGuard implements CanActivate {
20|  constructor(private readonly prisma: PrismaService) {}
21|
22|  async canActivate(context: ExecutionContext): Promise<boolean> {
23|    const request = context.switchToHttp().getRequest<Request>();
24|    const deviceId = request.headers['x-device-id'] as string
25|      || request.body?.deviceId
26|      || (request.params as any)?.deviceId;
27|
28|    if (!deviceId) {
29|      // No deviceId — allow through (auth guard handles general access)
30|      return true;
31|    }
32|
33|    const device = await this.prisma.device.findUnique({
34|      where: { deviceId },
35|      select: {
36|        driverId: true,
37|        lastHeartbeat: true,
38|        driver: {
39|          select: {
40|            subscriptionPaid: true,
41|            subscriptionEnd: true,
42|          },
43|        },
44|      },
45|    });
46|
47|    if (!device || !device.driver) {
48|      // Device not assigned to a driver — allow (new device setup scenario)
49|      return true;
50|    }
51|
52|    const driver = device.driver;
53|
54|    // Check if subscription is paid and not expired
55|    if (driver.subscriptionPaid && driver.subscriptionEnd && driver.subscriptionEnd > new Date()) {
56|      return true; // Active subscription
57|    }
58|
59|    // Grace period: if offline for >24h, allow 48h after subscription expiry
60|    if (device.lastHeartbeat) {
61|      const offlineThreshold = new Date(Date.now() - 24 * 60 * 60 * 1000);
62|      const isOffline = device.lastHeartbeat < offlineThreshold;
63|
64|      if (isOffline && driver.subscriptionEnd) {
65|        const gracePeriodEnd = new Date(driver.subscriptionEnd.getTime() + 48 * 60 * 60 * 1000);
66|        if (gracePeriodEnd > new Date()) {
67|          // Within 48h grace period — allow continued playback
68|          return true;
69|        }
70|      }
71|    }
72|
73|    // Subscription expired and no grace period — block
74|    throw new HttpException(
75|      {
76|        statusCode: 402,
77|        message: 'Subscription expired. Payment required to continue service.',
78|        reason: 'SUBSCRIPTION_EXPIRED',
79|        deviceId,
80|      },
81|      HttpStatus.PAYMENT_REQUIRED,
82|    );
83|  }
