{"content": "1|import { useEffect, useRef } from 'react';
2|import { supabase } from '@tad/services';
3|import { usePaymentStore } from '../store/usePaymentStore';
4|import { openDB } from 'idb';
5|
6|const DB_NAME = 'tad_telemetry_db';
7|const STORE_NAME = 'gps_buffer';
8|const POSTGREST_RPC_URL = `${process.env.NEXT_PUBLIC_SUPABASE_URL}/rest/v1/rpc/bulk_insert_telemetry`;
9|const ANON_KEY = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
10|
11|/**
12| * useBackgroundTelemetry — Dual-channel telemetry hook (v12.2.5)
13| *
14| * Channels:
15| *  1. Supabase Realtime (Live Pings): telemetry_ping every 30s
16| *  2. HTTP Batch Sync: POST /fleet/track-batch every 5 minutes
17| *
18| * REVENUE SHIELD v12.2.5:
19| *  - HTTP 402/403 responses trigger killSwitch via usePaymentStore.setLock()
20| *  - Grace period: 48h continued playback after subscription expiry when offline
21| *  - Subscription status cached in localStorage for offline resilience
22| *  - FORCE_KILL_SWITCH flag cached for cross-hook propagation
23| */
24|const GRACE_PERIOD_MS = 48 * 60 * 60 * 1000; // 48 hours
25|const SUBSCRIPTION_CACHE_KEY = 'TAD_SUBSCRIPTION_STATUS';
26|const SUBSCRIPTION_EXPIRY_KEY = 'TAD_SUBSCRIPTION_EXPIRY';
27|
28|export const useBackgroundTelemetry = (driverId: string) => {
29|  const lastSyncTime = useRef<number>(0);
30|  const lastLivePingTime = useRef<number>(0);
31|  const watchIdRef = useRef<number | null>(null);
32|  const suspendedRef = useRef<boolean>(false);
33|  const { setLock } = usePaymentStore();
34|
35|  useEffect(() => {
36|    if (!driverId) return;
37|    if (!('geolocation' in navigator)) return;
38|
39|    // IDB Setup
40|    const dbPromise = openDB(DB_NAME, 1, {
41|      upgrade(db) {
42|        if (!db.objectStoreNames.contains(STORE_NAME)) {
43|          db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
44|        }
45|      },
46|    });
47|
48|    // Check for cached killSwitch from another hook (e.g. useTelemetry)
49|    const cachedKill = localStorage.getItem('TAD_FORCE_KILL_SWITCH');
50|    if (cachedKill === 'true') {
51|      // Check if we're still within the grace period
52|      const cachedExpiry = localStorage.getItem(SUBSCRIPTION_EXPIRY_KEY);
53|      if (cachedExpiry) {
54|        const expiryDate = new Date(cachedExpiry);
55|        const gracePeriodEnd = new Date(expiryDate.getTime() + GRACE_PERIOD_MS);
56|        if (gracePeriodEnd > new Date()) {
57|          // Within grace period — temporarily re-allow telemetry
58|          suspendedRef.current = false;
59|          console.warn('[TAD] Within 48h grace period after subscription expiry. Telemetry continues.');
60|        } else {
61|          // Grace period expired — remain suspended
62|          suspendedRef.current = true;
63|          return;
64|        }
65|      } else {
66|        suspendedRef.current = true;
67|        return; // Don't start tracking if already suspended without expiry info
68|      }
69|    }
70|
71|    const liveChannel = supabase.channel('fleet_tracking_live', {
72|      config: { broadcast: { ack: true } },
73|    });
74|
75|    liveChannel.subscribe((status, error) => {
76|      if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT' || status === 'CLOSED') {
77|        console.error('[TAD_REALTIME][DRIVER] Broadcast channel rejected or closed', {
78|          status,
79|          error,
80|          channel: 'fleet_tracking_live',
81|        });
82|      }
83|    });
84|
85|    const handleSuspension = (subscriptionEnd?: string) => {
86|      // ── REVENUE SHIELD: Kill-Switch enforcement ──
87|      suspendedRef.current = true;
88|
89|      // Cache subscription expiry for grace period calculation
90|      if (subscriptionEnd) {
91|        localStorage.setItem(SUBSCRIPTION_EXPIRY_KEY, subscriptionEnd);
92|      }
93|
94|      // Cache flag in localStorage for cross-hook propagation
95|      localStorage.setItem('TAD_FORCE_KILL_SWITCH', 'true');
96|      localStorage.setItem(SUBSCRIPTION_CACHE_KEY, 'SUSPENDED');
97|
98|      // Activate PaymentLockOverlay
99|      setLock(true, 'Suscripción vencida. Pago de RD$6,000 requerido.');
100|
101|      // Stop GPS tracking
102|      if (watchIdRef.current !== null) {
103|        navigator.geolocation.clearWatch(watchIdRef.current);
104|        watchIdRef.current = null;
105|      }
106|
107|      // Destroy Supabase Realtime channel
108|      void supabase.removeChannel(liveChannel);
109|    };
110|
111|    const clearSuspension = () => {
112|      suspendedRef.current = false;
113|      localStorage.removeItem('TAD_FORCE_KILL_SWITCH');
114|      localStorage.removeItem(SUBSCRIPTION_EXPIRY_KEY);
115|      localStorage.setItem(SUBSCRIPTION_CACHE_KEY, 'ACTIVE');
116|      setLock(false, '');
117|    };
118|
119|    watchIdRef.current = navigator.geolocation.watchPosition(
120|      (position) => {
121|        // Block all telemetry if suspended
122|        if (suspendedRef.current) return;
123|
124|        const now = Date.now();
125|        const isOnline = (localStorage.getItem('TAD_DRIVER_STATUS') || 'ONLINE').toUpperCase() === 'ONLINE';
126|
127|        if (isOnline && now - lastLivePingTime.current >= 30000) {
128|          lastLivePingTime.current = now;
129|          const ping = {
130|            driverId,
131|            deviceId: localStorage.getItem('TAD_DEVICE_ID') || 'unknown',
132|            lat: position.coords.latitude,
133|            lng: position.coords.longitude,
134|            speed: position.coords.speed || 0,
135|            bearing: position.coords.heading || 0,
136|            timestamp: new Date(position.timestamp).toISOString(),
137|          };
138|
139|          void liveChannel.send({
140|            type: 'broadcast',
141|            event: 'telemetry_ping',
142|            payload: ping,
143|          }).then((status) => {
144|            if (status !== 'ok') {
145|              console.error('[TAD_REALTIME][DRIVER] telemetry_ping was not acknowledged', {
146|                status,
147|                channel: 'fleet_tracking_live',
148|                driverId,
149|              });
150|            }
151|          }).catch((error) => {
152|            console.error('[TAD_REALTIME][DRIVER] telemetry_ping publish failed', error);
153|          });
154|        }
155|
156|        // 1. Acumular punto en el Buffer Local (IndexedDB)
157|        const addPoint = async () => {
158|          const db = await dbPromise;
159|          await db.add(STORE_NAME, {
160|            device_id: localStorage.getItem('TAD_DEVICE_ID') || 'unknown',
161|            driver_id: driverId,
162|            latitude: position.coords.latitude,
163|            longitude: position.coords.longitude,
164|            speed: position.coords.speed || 0,
165|            captured_at: new Date(position.timestamp).toISOString(),
166|          });
167|        };
168|        addPoint().catch(console.error);
169|
170|        // 5-minute debounce for bulk flush (300,000 ms)
171|        if (now - lastSyncTime.current < 300000) return;
172|        
173|        // No sincronizar si no hay red
174|        if (!navigator.onLine) return;
175|        
176|        lastSyncTime.current = now;
177|
178|        const flushBatch = async () => {
179|          const db = await dbPromise;
180|          const allRecords = await db.getAll(STORE_NAME);
181|          if (allRecords.length === 0) return;
182|
183|          try {
184|            const response = await fetch(POSTGREST_RPC_URL, {
185|              method: 'POST',
186|              headers: {
187|                'Content-Type': 'application/json',
188|                'apikey': ANON_KEY!,
189|                'Authorization': `Bearer ${ANON_KEY}`,
190|              },
191|              body: JSON.stringify({ telemetry_payload: allRecords }),
192|            });
193|
194|            if (response.status === 402 || response.status === 403) {
195|              // Manejo de Error 402/403 de RLS/Supabase
196|              response.json().then((body) => {
197|                const subscriptionEnd = body?.subscriptionEnd || body?.subscription_end;
198|                handleSuspension(subscriptionEnd);
199|              }).catch(() => handleSuspension());
200|              return;
201|            }
202|
203|            if (response.ok) {
204|              const tx = db.transaction(STORE_NAME, 'readwrite');
205|              await tx.store.clear();
206|              await tx.done;
207|              clearSuspension();
208|            } else {
209|              console.error('[TELEMETRY_HTTP] Non-OK response:', response.status);
210|            }
211|          } catch (err) {
212|            console.error('Error flushing telemetry batch to PostgREST:', err);
213|          }
214|        };
215|        flushBatch();
216|      },
217|      (error) => {
218|        console.error('Geolocation error:', error);
219|      },
220|      {
221|        enableHighAccuracy: true,
222|        timeout: 10000,
223|        maximumAge: 0,
224|      }
225|    );
