2|/**
3| * useTelemetry — Hook de Telemetría Offline-First con soporte para IndexedDB
4| *
5| * Reglas de negocio:
6| *  - Agrupa coordenadas en lotes de BATCH_SIZE (10) o flushea cada FLUSH_INTERVAL_MS (300s)
7| *  - Almacena el buffer en IndexedDB para mayor resiliencia
8| *  - Al recibir HTTP 402 del backend → destruye el worker GPS y activa el kill-switch
9| *  - Sin dependencias de librerías de UI externas
10| */
11|
12|import { useEffect, useRef, useCallback, useState } from 'react';
13|import { usePaymentStore } from '../store/usePaymentStore';
14|import { openDB } from '../utils/indexedDb';
15|
16|// ─── Constantes ──────────────────────────────────────────────────────────────
17|const BATCH_SIZE = 10;
18|const FLUSH_INTERVAL_MS = 300_000; // 5 minutos (debounce estricto V12)
19|const MAX_OFFLINE_RECORDS = 500;
20|
21|export type ConnectionStatus = 'online' | 'offline' | 'syncing';
22|
23|export interface TelemetryCoord {
24|  lat: number;
25|  lng: number;
26|  ts: number;
27|  accuracy?: number;
28|}
29|
30|export interface UseTelemetryReturn {
31|  connectionStatus: ConnectionStatus;
32|  batchCount: number;     // coordenadas actuales en el buffer (0–10)
33|  offlineCount: number;   // registros guardados offline pendientes de sync
34|  syncPending: () => Promise<{ processed: number; remaining: number; success: boolean }>;
35|  startTracking: () => void;
36|  stopTracking: () => void;
37|  isTracking: boolean;
38|}
39|
40|// ─── Helpers IndexedDB ────────────────────────────────────────────────────────
41|async function readCoordsByStatus(status: 'batch' | 'offline'): Promise<TelemetryCoord[]> {
42|  try {
43|    const db = await openDB();
44|    const tx = db.transaction('telemetry', 'readonly');
45|    const store = tx.objectStore('telemetry');
46|    return new Promise((resolve) => {
47|      const request = store.getAll();
48|      request.onsuccess = () => {
49|        const all = request.result || [];
50|        resolve(all.filter((x: any) => x.status === status));
51|      };
52|      request.onerror = () => resolve([]);
53|    });
54|  } catch (err) {
55|    console.error('IndexedDB read error:', err);
56|    return [];
57|  }
58|}
59|
60|async function writeBatchCoords(batch: TelemetryCoord[]): Promise<void> {
61|  try {
62|    const db = await openDB();
63|    const tx = db.transaction('telemetry', 'readwrite');
64|    const store = tx.objectStore('telemetry');
65|    
66|    return new Promise<void>((resolve) => {
67|      const allRequest = store.getAll();
68|      allRequest.onsuccess = () => {
69|        const all = allRequest.result || [];
70|        const batchKeys = all.filter((x: any) => x.status === 'batch').map((x: any) => x.ts);
71|        batchKeys.forEach((key: number) => store.delete(key));
72|        
73|        batch.forEach((coord) => {
74|          store.put({ ...coord, status: 'batch' });
75|        });
76|        resolve();
77|      };
78|      allRequest.onerror = () => resolve();
79|    });
80|  } catch (err) {
81|    console.error('IndexedDB writeBatch error:', err);
82|  }
83|}
84|
85|async function appendOfflineCoords(coords: TelemetryCoord[]): Promise<void> {
86|  try {
87|    const db = await openDB();
88|    const tx = db.transaction('telemetry', 'readwrite');
89|    const store = tx.objectStore('telemetry');
90|    
91|    return new Promise<void>((resolve) => {
92|      const allRequest = store.getAll();
93|      allRequest.onsuccess = () => {
94|        const all = allRequest.result || [];
95|        const offlineRecords = all.filter((x: any) => x.status === 'offline');
96|        
97|        const merged = [...offlineRecords, ...coords];
98|        const toKeep = merged.slice(-MAX_OFFLINE_RECORDS);
99|        
100|        const toKeepKeys = new Set(toKeep.map((x) => x.ts));
101|        offlineRecords.forEach((x: any) => {
102|          if (!toKeepKeys.has(x.ts)) {
103|            store.delete(x.ts);
104|          }
105|        });
106|        
107|        toKeep.forEach((coord) => {
108|          store.put({ ...coord, status: 'offline' });
109|        });
110|        resolve();
111|      };
112|      allRequest.onerror = () => resolve();
113|    });
114|  } catch (err) {
115|    console.error('IndexedDB appendOffline error:', err);
116|  }
117|}
118|
119|async function clearOfflineCoords(): Promise<void> {
120|  try {
121|    const db = await openDB();
122|    const tx = db.transaction('telemetry', 'readwrite');
123|    const store = tx.objectStore('telemetry');
124|    return new Promise<void>((resolve) => {
125|      const allRequest = store.getAll();
126|      allRequest.onsuccess = () => {
127|        const all = allRequest.result || [];
128|        const offlineKeys = all.filter((x: any) => x.status === 'offline').map((x: any) => x.ts);
129|        offlineKeys.forEach((key: number) => store.delete(key));
130|        resolve();
131|      };
132|      allRequest.onerror = () => resolve();
133|    });
134|  } catch (err) {
135|    console.error('IndexedDB clearOffline error:', err);
136|  }
137|}
138|
139|async function writeOfflineCoords(coords: TelemetryCoord[]): Promise<void> {
140|  try {
141|    const db = await openDB();
142|    const tx = db.transaction('telemetry', 'readwrite');
143|    const store = tx.objectStore('telemetry');
144|    return new Promise<void>((resolve) => {
145|      const allRequest = store.getAll();
146|      allRequest.onsuccess = () => {
147|        const all = allRequest.result || [];
148|        const offlineKeys = all.filter((x: any) => x.status === 'offline').map((x: any) => x.ts);
149|        offlineKeys.forEach((key: number) => store.delete(key));
150|        
151|        coords.slice(-MAX_OFFLINE_RECORDS).forEach((coord) => {
152|          store.put({ ...coord, status: 'offline' });
153|        });
154|        resolve();
155|      };
156|      allRequest.onerror = () => resolve();
157|    });
158|  } catch (err) {
159|    console.error('IndexedDB writeOffline error:', err);
160|  }
161|}
162|
163|// ─── Hook Principal ───────────────────────────────────────────────────────────
164|export function useTelemetry(): UseTelemetryReturn {
165|  const { setLock } = usePaymentStore();
166|
167|  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>(
168|    typeof navigator !== 'undefined' && !navigator.onLine ? 'offline' : 'online'
169|  );
170|  const [batchCount, setBatchCount] = useState<number>(0);
171|  const [offlineCount, setOfflineCount] = useState<number>(0);
172|  const [isTracking, setIsTracking] = useState(false);
173|
174|  // Refs para evitar closures obsoletos
175|  const watchIdRef = useRef<number | null>(null);
176|  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
177|  const isOnlineRef = useRef(typeof navigator !== 'undefined' ? navigator.onLine : true);
178|  const wakeLockRef = useRef<any>(null); // Screen Wake Lock sentinel
179|
180|  // ─── Memoria persistente durante la sesión ─────────────────────────────
181|  const memoryBufferRef = useRef<TelemetryCoord[]>([]);
182|
183|  const resolveApiBase = useCallback(() => '/api/proxy', []);
184|
185|  // Hidratar contadores iniciales desde IndexedDB
186|  useEffect(() => {
187|    async function hydrate() {
188|      const batch = await readCoordsByStatus('batch');
189|      const offline = await readCoordsByStatus('offline');
190|      setBatchCount(batch.length);
191|      setOfflineCount(offline.length);
192|    }
193|    hydrate();
194|  }, []);
195|
196|  const buildTelemetryPayload = useCallback((driverId: string, deviceId: string, points: TelemetryCoord[]) => {
197|    return {
198|      driverId,
199|      deviceId,
200|      points: points.map((coord) => ({
201|        lat: coord.lat,
202|        lng: coord.lng,
203|        speed: 0,
204|        timestamp: coord.ts,
205|      })),
206|    };
207|  }, []);
208|
209|  const postTrackBatch = useCallback(async (
210|    apiBase: string,
211|    driverId: string,
212|    deviceId: string,
213|    points: TelemetryCoord[]
214|  ) => {
215|    return fetch(`${apiBase}/fleet/track-batch`, {
216|      method: 'POST',
217|      headers: { 'Content-Type': 'application/json' },
218|      credentials: 'include',
219|      body: JSON.stringify(buildTelemetryPayload(driverId, deviceId, points)),
220|      signal: AbortSignal.timeout(15_000),
221|    });
222|  }, [buildTelemetryPayload]);
223|
224|  const syncOfflineQueue = useCallback(async (
225|    apiBase: string,
226|    driverId: string,
227|    deviceId: string
228|  ) => {
229|    const DRIP_CHUNK_SIZE = 50;
230|    let processed = 0;
231|    let remainingQueue = await readCoordsByStatus('offline');
232|
233|    while (remainingQueue.length > 0) {
234|      const chunk = remainingQueue.slice(0, DRIP_CHUNK_SIZE);
235|
236|      try {
237|        const retryRes = await postTrackBatch(apiBase, driverId, deviceId, chunk);
238|        if (retryRes.status === 402) {
239|          setLock(true, 'Suscripción vencida. Pago de RD$6,000 requerido.');
240|          setConnectionStatus('offline');
241|          break;
242|        }
243|        if (!retryRes.ok) {
244|          break;
245|        }
246|      } catch {
247|        break;
248|      }
249|
250|      processed += chunk.length;
251|      remainingQueue = remainingQueue.slice(chunk.length);
252|      await writeOfflineCoords(remainingQueue);
253|      setOfflineCount(remainingQueue.length);
254|
255|      if (remainingQueue.length > 0) {
256|        await new Promise((resolve) => setTimeout(resolve, Math.random() * 1500 + 300));
257|      }
258|    }
259|
260|    if (remainingQueue.length === 0) {
261|      await clearOfflineCoords();
262|      setOfflineCount(0);
263|    }
264|
265|    return {
266|      processed,
267|      remaining: remainingQueue.length,
268|      success: remainingQueue.length === 0,
269|    };
270|  }, [postTrackBatch, setLock]);
271|
272|  // ─── Flush: envía el batch al backend ────────────────────────────────────
273|  const flushBatch = useCallback(async (forceFlush = false) => {
274|    // 1. Sincronizar memoria con storage antes de procesar
275|    const storageBatch = await readCoordsByStatus('batch');
276|    const combinedBatch = [...storageBatch, ...memoryBufferRef.current];
277|
278|    if (combinedBatch.length === 0) return;
279|    if (!forceFlush && combinedBatch.length < BATCH_SIZE) return;
280|
281|    // Limpiar buffers inmediatamente para evitar duplicados en re-entradas
282|    memoryBufferRef.current = [];
283|    await writeBatchCoords([]);
284|
285|    if (!isOnlineRef.current) {
286|      // Sin red → guardar en cola offline
287|      await appendOfflineCoords(combinedBatch);
288|      setBatchCount(0);
289|      const offlineLen = (await readCoordsByStatus('offline')).length;
290|      setOfflineCount(offlineLen);
291|      return;
292|    }
293|
294|    setConnectionStatus('syncing');
295|
296|    try {
297|      const apiBase = resolveApiBase();
298|
299|      const userRaw = localStorage.getItem('tad_driver_user');
300|      const user = userRaw ? JSON.parse(userRaw) : null;
301|      const driverId = user?.entityId || 'unknown';
302|      const deviceId = localStorage.getItem('TAD_DEVICE_ID') || 'unknown';
303|
304|      // Evita enviar telemetría inválida durante onboarding/login sin identidad aún resuelta.
305|      if (driverId === 'unknown' || deviceId === 'unknown') {
306|        await appendOfflineCoords(combinedBatch);
307|        setBatchCount(0);
308|        const offlineLen = (await readCoordsByStatus('offline')).length;
309|        setOfflineCount(offlineLen);
310|        setConnectionStatus('offline');
311|        return;
312|      }
313|
314|      const res = await postTrackBatch(apiBase, driverId, deviceId, combinedBatch);
315|
316|      if (res.status === 402) {
317|        stopTracking();
318|        setLock(true, 'Suscripción vencida. Pago de RD$6,000 requerido.');
319|        setConnectionStatus('offline');
320|        return;
321|      }
322|
323|      if (!res.ok) throw new Error(`HTTP ${res.status}`);
324|
325|      setBatchCount(0);
326|
327|      const offlineQueue = await readCoordsByStatus('offline');
328|      if (offlineQueue.length > 0) {
329|        const syncResult = await syncOfflineQueue(apiBase, driverId, deviceId);
330|        if (!syncResult.success) {
331|          setConnectionStatus('offline');
332|          return;
333|        }
334|      }
335|
336|      setConnectionStatus('online');
337|    } catch {
338|      // Re-encolar si falló el envío
339|      await appendOfflineCoords(combinedBatch);
340|      setBatchCount(0);
341|      const offlineLen = (await readCoordsByStatus('offline')).length;
342|      setOfflineCount(offlineLen);
343|      setConnectionStatus('offline');
344|    }
345|  }, [postTrackBatch, resolveApiBase, setLock, syncOfflineQueue]);
346|
347|  const syncPending = useCallback(async () => {
348|    const userRaw = localStorage.getItem('tad_driver_user');
349|    const user = userRaw ? JSON.parse(userRaw) : null;
350|    const driverId = user?.entityId || 'unknown';
351|    const deviceId = localStorage.getItem('TAD_DEVICE_ID') || 'unknown';
352|    const apiBase = resolveApiBase();
353|
354|    const offlineQueue = await readCoordsByStatus('offline');
355|    if (!isOnlineRef.current) {
356|      setConnectionStatus('offline');
357|      return { processed: 0, remaining: offlineQueue.length, success: false };
358|    }
359|
360|    setConnectionStatus('syncing');
361|    const result = await syncOfflineQueue(apiBase, driverId, deviceId);
362|    setConnectionStatus(result.success ? 'online' : 'offline');
363|    return result;
364|  }, [resolveApiBase, syncOfflineQueue]);
365|
366|  // ─── Inicializar flush periódico ──────────────────────────────────────────
367|  const resetFlushTimer = useCallback(() => {
368|    if (flushTimerRef.current) clearTimeout(flushTimerRef.current);
369|    flushTimerRef.current = setTimeout(() => {
370|      flushBatch(true);
371|      resetFlushTimer();
372|    }, FLUSH_INTERVAL_MS);
373|  }, [flushBatch]);
374|
375|  // ─── Añadir coordenada al batch (OPTIMIZADO: Memoria primero) ─────────────
376|  const addCoord = useCallback((coord: TelemetryCoord) => {
377|    memoryBufferRef.current.push(coord);
378|    setBatchCount(prev => prev + 1);
379|    writeBatchCoords(memoryBufferRef.current);
380|
381|    // Persistir a disco solo si el buffer es grande o cada X tiempo 
382|    // para evitar I/O constante en cada segundo de GPS
383|    if (memoryBufferRef.current.length >= BATCH_SIZE) {
384|      flushBatch(false);
385|    }
386|  }, [flushBatch]);
387|
388|  // ─── startTracking ────────────────────────────────────────────────────────
389|  const startTracking = useCallback(() => {
390|    if (watchIdRef.current !== null) return; // ya está activo
391|    if (typeof navigator === 'undefined' || !navigator.geolocation) return;
392|
393|    setIsTracking(true);
394|    resetFlushTimer();
395|
396|    // ─── Activar Screen Wake Lock ──────────────────────────────────────────
397|    if ('wakeLock' in navigator && document.visibilityState === 'visible') {
398|      void (navigator as any).wakeLock.request('screen')
399|        .then((lock: any) => {
400|          wakeLockRef.current = lock;
401|          if (process.env.NODE_ENV !== 'production') {
402|            console.log('[useTelemetry] Screen Wake Lock activo');
403|          }
404|        })
405|        .catch((err: any) => {
406|          if (process.env.NODE_ENV !== 'production') {
407|            console.warn('[useTelemetry] Wake Lock no disponible:', err?.message || err);
408|          }
409|        });
410|    }
411|
412|    watchIdRef.current = navigator.geolocation.watchPosition(
413|      (pos) => {
414|        addCoord({
415|          lat: pos.coords.latitude,
416|          lng: pos.coords.longitude,
417|          ts: pos.timestamp,
418|          accuracy: pos.coords.accuracy,
419|        });
420|      },
421|      (err) => {
422|        // Error de GPS (permisos denegados, etc.) — no fatal
423|        if (process.env.NODE_ENV !== 'production') {
424|          console.warn('[useTelemetry] GPS error:', err.code, err.message);
425|        }
426|      },
427|      {
428|        enableHighAccuracy: true,
429|        maximumAge: 10_000,
430|        timeout: 15_000,
431|      }
432|    );
433|  }, [addCoord, resetFlushTimer]);
434|
435|  // ─── stopTracking (Kill-Switch) ───────────────────────────────────────────
436|  const stopTracking = useCallback(() => {
437|    if (watchIdRef.current !== null) {
438|      navigator.geolocation.clearWatch(watchIdRef.current);
439|      watchIdRef.current = null;
440|    }
441|    if (flushTimerRef.current) {
442|      clearTimeout(flushTimerRef.current);
443|      flushTimerRef.current = null;
444|    }
445|
446|    // ─── Liberar Wake Lock ────────────────────────────────────────────────
447|    if (wakeLockRef.current) {
448|      wakeLockRef.current.release().then(() => {
449|        wakeLockRef.current = null;
450|      });
451|    }
452|
453|    setIsTracking(false);
454|  }, []);
455|
456|  // ─── Listeners de red ─────────────────────────────────────────────────────
457|  useEffect(() => {
458|    const handleOnline = () => {
459|      isOnlineRef.current = true;
460|      readCoordsByStatus('offline').then((offlineQueue) => {
461|        if (offlineQueue.length > 0) {
462|          void syncPending();
463|          return;
464|        }
465|        setConnectionStatus('online');
466|        void flushBatch(true);
467|      });
468|    };
469|    const handleOffline = () => {
470|      isOnlineRef.current = false;
471|      setConnectionStatus('offline');
472|    };
473|
474|    window.addEventListener('online', handleOnline);
475|    window.addEventListener('offline', handleOffline);
476|
477|    // Escuchar mensaje del Service Worker para flush
478|    const handleSWMessage = (evt: MessageEvent) => {
479|      if (evt.data?.type === 'FLUSH_TELEMETRY') {
480|        flushBatch(true);
481|      }
482|    };
483|    navigator.serviceWorker?.addEventListener('message', handleSWMessage);
484|
485|    return () => {
486|      window.removeEventListener('online', handleOnline);
487|      window.removeEventListener('offline', handleOffline);
488|      navigator.serviceWorker?.removeEventListener('message', handleSWMessage);
489|    };
490|  }, [flushBatch, syncPending]);
491|
492|  // ─── Cleanup al desmontar ─────────────────────────────────────────────────
493|  useEffect(() => {
494|    return () => {
495|      stopTracking();
496|    };
497|  }, [stopTracking]);
498|
499|  return {
500|    connectionStatus,
