10|@Injectable()
11|export class FinanceService {
12|  private readonly logger = new Logger(FinanceService.name);
13|  private readonly PAY_PER_AD = BUSINESS_RULES.DRIVER_RATE_PER_CAMPAIGN_RD; // RD$500 per active ad
14|
15|  constructor(
16|    private readonly prisma: PrismaService,
17|    private readonly invoiceService: InvoiceService,
18|    private readonly whatsappService: WhatsAppService,
19|    private readonly emailService: EmailService
20|  ) { }
21|
22|  /**
23|   * RECOVERY: On module init, check if the system missed any critical delinquency scans
24|   */
25|  async onModuleInit() {
26|    this.logger.log('🔄 [RECOVERY] Checking for missed automated tasks...');
27|    await this.checkHighDelinquency();
28|  }
29|
30|  /**
31|   * Proceso de Notificación Automática por Morosidad (Regla 402)
32|   */
33|  async notifyMorosidad(deviceId: string) {
34|    this.logger.warn(`🚨 [FINANCE_ALERT] Triggering Morosidad Protocol for Device: ${deviceId}`);
35|
36|    const device = await this.prisma.device.findUnique({
37|      where: { deviceId },
38|      include: { driver: true }
39|    });
40|
41|    if (!device) return;
42|
43|    // 1. Generar la Factura SOS (PDF)
44|    const pdfBuffer = await this.invoiceService.generateDebtInvoicePDF({
45|      deviceId: device.deviceId,
46|      chofer: device.driver?.fullName || 'Socio TAD',
47|      placa: device.taxiNumber
48|    });
49|
50|    // 2. Real Notifications (WhatsApp only as Driver lacks email field in current schema)
51|    const driverPhone = device.driver?.phone;
52|    const driverName = device.driver?.fullName || 'Socio TAD';
53|
54|    if (driverPhone) {
55|      await this.whatsappService.sendDelinquencyAlert(driverPhone, driverName, device.deviceId);
56|      this.logger.log(`📱 [WHATSAPP_SENT] Alerta de Morosidad enviada a: ${driverPhone}`);
57|    }
58|
59|    // 3. Registrar el intento de cobro en el Ledger
60|    const amount = BUSINESS_RULES.STARTER_KIT_ANNUAL_FEE_RD;
61|    const taxAmount = (amount / (1 + BUSINESS_RULES.ITBIS_RATE)) * BUSINESS_RULES.ITBIS_RATE;
62|    const netAmount = amount - taxAmount;
63|
64|    await this.prisma.financialTransaction.create({
65|      data: {
66|        type: 'INCOMING',
67|        category: 'SUSCRIPCION',
68|        status: 'PENDING',
69|        amount,
70|        taxAmount,
71|        netAmount,
72|        entityId: device.driver?.id,
73|        reference: `REGLA-402-${deviceId.substring(0, 8)}`,
74|        note: `Factura de morosidad generada automáticamente por Kill-Switch.`
75|      }
76|    });
77|
78|    return { success: true, notified: !!driverPhone };
79|  }
