81|  /**
82|   * SCANNER CRON: Checks daily for drivers with unpaid subscriptions past due
83|   * and triggers the delinquency protocol.
84|   */
85|  @Cron(CronExpression.EVERY_DAY_AT_3AM)
86|  async checkHighDelinquency(targetDate: Date = new Date()) {
87|    this.logger.log(`🛡️ [CRON_DELINQUENCY] Iniciando escaneo de morosidad para fecha: ${targetDate.toDateString()}...`);
88|
89|    const delinquentDrivers = await this.prisma.driver.findMany({
90|      where: {
91|        status: BUSINESS_RULES.STATUS.DRIVER.ACTIVE,
92|        subscriptionPaid: false,
93|        subscriptionEnd: { lt: targetDate } // Past due
94|      },
95|      include: { devices: true }
96|    });
97|
98|    if (delinquentDrivers.length === 0) {
99|      this.logger.log(`✅ No hay morosos críticos detectados para ${targetDate.toDateString()}.`);
100|      return;
