114|  /**
115|   * Calculates the monthly payroll for all drivers.
116|   * Logic: RD$500 per each ACTIVE campaign assigned to any device of the driver.
117|   */
118|  async calculateMonthlyPayroll(month: number, year: number) {
119|    this.logger.log(`Calculating payroll for ${month}/${year}`);
120|
121|    // 1. Get all drivers and their associated devices
122|    const activeCampaigns = await this.prisma.campaign.findMany({
123|      where: { status: 'ACTIVE', active: true }
124|    });
125|
126|    const drivers = await this.prisma.driver.findMany({
127|      select: {
128|        id: true,
129|        fullName: true,
130|        phone: true,
131|        licensePlate: true,
132|        taxiNumber: true,
133|        subscriptionPaid: true,
134|        subscriptionEnd: true,
135|        devices: {
136|          select: {
137|            deviceId: true,
138|            city: true,
139|            taxiNumber: true,
140|            campaigns: {
141|              select: { campaign_id: true }
142|            }
143|          }
144|        },
145|        referrals: { select: { id: true } },
146|        referredAdvertisers: { select: { id: true } }
147|      }
148|    });
149|
150|    const periodStart = new Date(year, month - 1, 1);
151|    const periodEnd = new Date(year, month, 0, 23, 59, 59);
152|
153|    // OPTIMIZACIÓN: Pre-calcular todos los conteos de GPS y PLAYBACKS en una sola query
154|    this.logger.log(`🔍 [OPTIMIZACIÓN] Pre-calculando conteos GPS y PoP para ${drivers.length} choferes...`);
155|    const [gpsCountsRaw, playbackEventsRaw] = await Promise.all([
156|      this.prisma.driverLocation.groupBy({
157|        by: ['driverId'],
158|        where: { timestamp: { gte: periodStart, lte: periodEnd } },
159|        _count: { _all: true }
160|      }),
161|      this.prisma.playbackEvent.findMany({
162|        where: {
163|          timestamp: { gte: periodStart, lte: periodEnd },
164|          eventType: 'play_confirm',
165|          verified: true, // REVENUE SHIELD: Only count validated playback events
166|        },
167|        select: { deviceId: true, videoId: true }
168|      })
169|    ]);
170|
171|    // MAPAS para búsqueda rápida O(1)
172|    const gpsCountsMap = new Map(gpsCountsRaw.map(item => [item.driverId, item._count._all]));
173|
174|    // Mapear Playbacks a Driver (PoP - Proof of Play)
175|    // driverId -> Set of campaignIds played
176|    const driverPoPMap = new Map<string, Set<string>>();
177|
178|    // Necesitamos saber qué mediaId (videoId) pertenece a qué campaignId
179|    const mediaToCampaignRaw = await this.prisma.media.findMany({
180|      where: { campaign_id: { not: null } },
181|      select: { id: true, campaign_id: true }
182|    });
183|    const mediaToCampaignMap = new Map(mediaToCampaignRaw.map(m => [m.id, m.campaign_id]));
184|
185|    // Mapear Device a Driver
186|    const deviceToDriverMap = new Map<string, string>();
187|    drivers.forEach(d => {
188|      d.devices?.forEach(dev => deviceToDriverMap.set(dev.deviceId, d.id));
189|    });
190|
191|    playbackEventsRaw.forEach(evt => {
192|      const driverId = deviceToDriverMap.get(evt.deviceId);
193|      const campaignId = mediaToCampaignMap.get(evt.videoId);
194|      if (driverId && campaignId) {
195|        if (!driverPoPMap.has(driverId)) driverPoPMap.set(driverId, new Set());
196|        driverPoPMap.get(driverId).add(campaignId);
197|      }
198|    });
199|
200|    // REGLA PERFORMANCE: Process with throttledMap to avoid DB pool exhaustion
201|    const payroll = await throttledMap(drivers, async (driver) => {
202|      try {
203|        const gpsPointsCount = gpsCountsMap.get(driver.id) || 0;
204|        const playedCampaigns = driverPoPMap.get(driver.id) || new Set();
205|
206|        // 2. PARADIGMA PoP: Solo se paga por anuncios TRANSMITIDOS (confirmados por playback)
207|        // El driver debe tener suscripción paga para recibir el abono
208|        const isSubPaid = driver.subscriptionPaid && (!driver.subscriptionEnd || new Date(driver.subscriptionEnd) >= new Date());
209|
210|        const activeAdsCount = isSubPaid ? playedCampaigns.size : 0;
211|        const baseCommission = 0;
212|
213|        // Calculate referral commissions
214|        const referrals = driver.referrals ? driver.referrals.length : 0;
215|        const driverReferralBonus = referrals * BUSINESS_RULES.DRIVER_REFERRAL_BONUS_RD;
216|
217|        // Calculate advertiser referral commissions
218|        const advertiserReferrals = driver.referredAdvertisers ? driver.referredAdvertisers.length : 0;
219|        const advertiserReferralBonus = advertiserReferrals * BUSINESS_RULES.ADVERTISER_REFERRAL_BONUS_RD;
220|
221|        const adTransmissionIncome = activeAdsCount * this.PAY_PER_AD;
222|        const totalAmount = adTransmissionIncome + driverReferralBonus + advertiserReferralBonus;
223|
224|        // Enhanced: Get the actual taxi number from the assigned devices or driver record
225|        const actualTaxiNumber = driver.devices?.[0]?.taxiNumber || driver.taxiNumber || 'S/N';
226|
227|        // Check if already paid
228|        const paymentRecord = await this.prisma.payrollPayment.findUnique({
229|          where: { driverId_month_year: { driverId: driver.id, month, year } }
230|        });
231|
232|        return {
233|          driverId: driver.id,
234|          driverName: driver.fullName || 'TAD DRIVER',
235|          driverPhone: driver.phone || '',
236|          taxiNumber: actualTaxiNumber,
237|          activeAds: paymentRecord?.status === 'PAID' ? paymentRecord.activeAds : activeAdsCount,
238|          adIncome: adTransmissionIncome,
239|          baseCommission,
240|          gpsPoints: paymentRecord?.status === 'PAID' ? paymentRecord.gpsPoints : gpsPointsCount,
241|          referralBonus: driverReferralBonus,
242|          advertiserReferralBonus,
243|          totalAmount: paymentRecord?.status === 'PAID' ? paymentRecord.amount : totalAmount,
244|          currency: 'DOP',
245|          status: paymentRecord?.status || 'PENDING',
246|          paidAt: paymentRecord?.paidAt,
247|          reference: paymentRecord?.referenceNum
248|        };
249|      } catch (err) {
250|        this.logger.error(`CRITICAL: Failed to calculate payroll for driver ${driver.id}: ${err.message}`);
251|        return {
252|          driverId: driver.id,
253|          driverName: (driver as any).fullName || 'ERROR',
254|          driverPhone: (driver as any).phone || '',
255|          taxiNumber: 'ERR',
256|          activeAds: 0,
257|          adIncome: 0,
258|          baseCommission: 0,
259|          gpsPoints: 0,
260|          referralBonus: 0,
261|          advertiserReferralBonus: 0,
262|          totalAmount: 0,
263|          currency: 'DOP',
264|          status: 'ERROR',
265|          error: true
266|        };
267|      }
268|    }, 5);
269|
270|    return payroll;
271|
272|  }
