290|    const payrollData = await this.calculateMonthlyPayroll(month, year);
291|    const recordsToCreate = payrollData
292|      .filter(p => p.totalAmount > 0)
293|      .map(p => ({
294|        driverId: p.driverId,
295|        month,
296|        year,
297|        amount: p.totalAmount,
298|        status: 'PENDING',
