640|  async broadcastCommand(type: string, params: Record<string, any> = {}) {
641|    Logger.log(`[FLEET_C2] Broadcasting global command: ${type}`);
642|
643|    // 1. Emitir vía Realtime para efectos inmediatos en dispositivos conectados
644|    await this.supabaseService.broadcastEvent('fleet_sync', 'WAKE_UP_CALL', {
