704|   * R3: Kill-Switch si la suscripción no está al día.
705|   * R2: Inserción masiva para optimizar latencia en producción.
706|   */
707|  async ingestTelemetryBatch(data: TrackBatchDto) {
708|    const logger = new Logger('FleetService');
709|    
710|    // 1. Validar existencia del conductor
711|    const driver = await this.prisma.driver.findUnique({
712|      where: { id: data.driverId },
713|      select: { id: true, subscriptionPaid: true, status: true, fullName: true }
714|    });
715|
716|    if (!driver) {
717|      logger.warn(`⚠️ Telemetry Rejected: Driver [${data.driverId}] not found.`);
718|      throw new HttpException('Driver Not Found', HttpStatus.NOT_FOUND);
719|    }
720|
721|    // 2. Regla de Negocio #3: Kill-Switch si la suscripción no está al día
722|    if (driver.status !== BUSINESS_RULES.STATUS.DRIVER.ACTIVE || !driver.subscriptionPaid) {
723|      logger.warn(`🚫 Telemetry Rejected (402): Driver [${driver.fullName}] is delinquent or inactive.`);
724|      throw new HttpException('Payment Required - Subscription Inactive', HttpStatus.PAYMENT_REQUIRED);
725|    }
726|
727|    // 3. Inserción Masiva (Batching) para optimizar I/O (Regla de Negocio #2)
728|    const telemetryData = data.points.map(p => ({
729|      driverId: data.driverId,
730|      deviceId: data.deviceId,
731|      latitude: p.lat,
732|      longitude: p.lng,
733|      speed: p.speed,
734|      timestamp: new Date(p.timestamp),
735|    }));
736|
737|    const result = await this.prisma.driverLocation.createMany({
738|      data: telemetryData,
739|      skipDuplicates: true,
740|    });
741|
742|    logger.log(`✅ Telemetry Batch Processed: ${result.count} points from [${driver.fullName}]`);
743|    
744|    // 4. Update Device 'lastSeen' and current position
745|    if (data.points.length > 0) {
746|      const lastPoint = data.points[data.points.length - 1];
747|      await this.prisma.device.update({
748|        where: { deviceId: data.deviceId },
749|        data: {
750|          lastSeen: new Date(),
751|          lastLat: lastPoint.lat,
752|          lastLng: lastPoint.lng,
753|        }
754|      }).catch(e => logger.error(`Failed to update device status: ${e.message}`));
755|    }
756|
757|    return result;
758|  }
