2|import { WalletService } from './wallet.service';
3|import { IdempotencyInterceptor } from '../../common/interceptors/idempotency.interceptor';
4|import { Roles, UserRole } from '../auth/decorators/roles.decorator';
5|import { z } from 'zod';
6|
7|// Zod schema for Bank Info
8|export const BankInfoSchema = z.object({
9|  banco: z.string().min(3, 'El nombre del banco es muy corto'),
10|  cuenta: z.string().regex(/^\d{10,20}$/, 'Número de cuenta inválido (debe tener entre 10 y 20 dígitos)'),
11|  tipo: z.enum(['AHORRO', 'CORRIENTE']),
12|  cedula: z.string().regex(/^\d{11}$/, 'La cédula dominicana debe tener 11 dígitos'),
13|  ownerName: z.string().min(3).optional(),
14|});
15|
16|// Zod schema for Withdraw
17|const WithdrawSchema = z.object({
18|  amount: z.number().positive('El monto debe ser positivo').max(500000, 'El monto excede el límite permitido'),
19|});
20|
21|@Controller('wallet')
22|@Roles(UserRole.DRIVER)
23|export class WalletController {
24|  constructor(private readonly walletService: WalletService) {}
25|
26|  /**
27|   * SHELTER FIX A-S3: driverId se extrae SIEMPRE del JWT (req.user.entityId).
28|   * Nunca se acepta un driverId del body o query params para operaciones de escritura.
29|   */
30|  @Get('balance')
31|  async getBalance(@Req() req: any) {
32|    const driverId = this.extractDriverId(req);
33|    return this.walletService.getBalance(driverId);
34|  }
35|
36|  @Post('withdraw')
37|  @UseInterceptors(IdempotencyInterceptor)
38|  async withdraw(@Req() req: any, @Body() payload: any) {
39|    const driverId = this.extractDriverId(req);
40|
41|    // Validar monto con Zod
42|    const parsed = WithdrawSchema.safeParse(payload);
43|    if (!parsed.success) {
44|      throw new BadRequestException({
45|        code: 'VALIDATION_ERROR',
46|        message: parsed.error.errors.map((e) => e.message).join(', '),
47|      });
48|    }
49|
50|    return this.walletService.withdraw(driverId, parsed.data.amount);
51|  }
52|
53|  @Put('bank')
54|  @UseInterceptors(IdempotencyInterceptor)
55|  async updateBank(@Req() req: any, @Body() payload: any) {
56|    const driverId = this.extractDriverId(req);
57|
58|    // Validate with Zod
59|    const parsed = BankInfoSchema.safeParse(payload);
60|    if (!parsed.success) {
61|      throw new BadRequestException({
62|        code: 'VALIDATION_ERROR',
63|        message: parsed.error.errors.map((e) => e.message).join(', '),
64|      });
65|    }
66|
67|    return this.walletService.updateBank(driverId, parsed.data);
68|  }
69|
70|  /**
71|   * Extrae el driverId del token JWT validado por SupabaseAuthGuard.
72|   * Si el token no contiene entityId, deniega el acceso inmediatamente.
73|   */
74|  private extractDriverId(req: any): string {
75|    const entityId = req.user?.entityId;
76|    if (!entityId) {
77|      throw new UnauthorizedException(
78|        'Token de sesión inválido: no se encontró entityId. Reautentícate.'
79|      );
80|    }
81|    return entityId;
82|  }
