{"content": "1|import { Injectable, OnModuleInit, OnModuleDestroy, Logger } from '@nestjs/common';
2|import { PrismaClient } from '@prisma/client';
3|import * as fs from 'fs';
4|import * as path from 'path';
5|
6|@Injectable()
7|export class PrismaService extends PrismaClient implements OnModuleInit, OnModuleDestroy {
8|  private readonly logger = new Logger(PrismaService.name);
9|
10|  constructor() {
11|    let url = process.env.DATABASE_URL;
12|    let warnMsg: string | undefined;
13|    // SRE v12.1.1: Default 5 connections para Supabase Free Tier en EasyPanel.
14|    // 20 conexiones puede agotar el pool durante CRON bursts + heartbeat storms.
15|    if (url && !url.includes('connection_limit=')) {
16|      const separator = url.includes('?') ? '&' : '?';
17|      url = `${url}${separator}connection_limit=5`;
18|    } else if (url && url.includes('connection_limit=')) {
19|      const match = url.match(/connection_limit=(\d+)/);
20|      if (match && parseInt(match[1]) > 10) {
21|        warnMsg = `⚠️ [SRE] connection_limit=${match[1]} detectado en DATABASE_URL. Recomendado: 5 para EasyPanel Free Tier.`;
22|      }
23|    }
24|
25|    // SRE v12.2.5: pool_timeout=10s — evita que queries lentas bloqueen el pool durante spikes de telemetría
26|    if (url && !url.includes('pool_timeout=')) {
27|      const separator = url.includes('?') ? '&' : '?';
28|      url = `${url}${separator}pool_timeout=10`;
29|    }
30|
31|    super({
32|      datasources: {
33|        db: {
34|          // REGLA SRE: Forzar el uso del Pooler de Supabase (Puerto 6543)
35|          // DATABASE_URL debe incluir ?connection_limit=5 en EasyPanel
36|          url,
37|        },
38|      },
39|      // Solo loguear errores en producción para no saturar el log de EasyPanel
40|      log: process.env.NODE_ENV === 'development' ? ['query', 'info', 'warn', 'error'] : ['error'],
41|    });
42|
43|    if (warnMsg) {
44|      this.logger.warn(warnMsg);
45|    }
46|  }
47|
48|  async onModuleInit() {
49|    this.logger.log('🔌 Inicializando conexión al Pooler de Supabase...');
50|
51|    const MAX_RETRIES = 5;
52|    let attempts = 0;
53|
54|    while (attempts < MAX_RETRIES) {
55|      try {
56|        await this.$connect();
57|        this.logger.log(`✅ Conexión establecida con éxito en el intento ${attempts + 1}`);
58|
59|        // Async background initialization to keep startup lean
60|        this.initializeSreViews().catch(e => {
61|          this.logger.error(`❌ Fallo en inicialización de fondo: ${e.message}`);
62|        });
63|
64|        return;
65|      } catch (e) {
66|        attempts++;
67|        const delay = attempts * 2000;
68|        this.logger.error(`❌ Intento ${attempts}/${MAX_RETRIES} fallido al conectar a Supabase. Reintentando en ${delay / 1000}s...`);
69|        if (attempts >= MAX_RETRIES) {
70|          this.logger.error('🚨 ERROR FATAL: No se pudo conectar a la base de datos tras 5 intentos.');
71|          // Don't exit immediately, let Nest trial continue if possible, or use a health check
72|          return;
73|        }
74|        await new Promise(resolve => setTimeout(resolve, delay));
75|      }
76|    }
77|  }
78|
79|  /**
80|   * REGLA SRE: Inicializar Vistas Materializadas en segundo plano
81|   */
82|  private async initializeSreViews() {
83|    try {
84|      this.logger.log('🏗️ Sincronizando Vistas Materializadas (Master Sync)...');
85|      const viewsFile = path.resolve(process.cwd(), 'prisma/views.sql');
86|
87|      if (!fs.existsSync(viewsFile)) {
88|        this.logger.warn('⚠️ No se encontró prisma/views.sql. Saltando.');
89|        return;
90|      }
91|
92|      const sql = fs.readFileSync(viewsFile, 'utf8');
93|      const queries = sql.split(';').map((q: string) => q.trim()).filter((q: string) => q.length > 0);
94|
95|      for (const query of queries) {
96|        await this.$executeRawUnsafe(query).catch(e => {
97|          if (!e.message.includes('already exists')) {
98|            this.logger.error(`Error SQL en vista: ${e.message}`);
99|          }
100|        });
101|      }
102|      this.logger.log('✅ Master Sync Views configuradas.');
103|    } catch (viewError) {
104|      this.logger.error(`❌ Fallo al cargar script de vistas: ${viewError.message}`);
105|    }
106|  }
107|
108|  // REGLA SRE: Cerrar conexiones zombie al re-desplegar en EasyPanel
109|  async onModuleDestroy() {
110|    this.logger.log('🔌 Cierre de conexiones al Pooler solicitado (Shutdown/Redeploy)...');
111|    await this.$disconnect();
112|  }
113|
114|  /**
115|   * Refresca la vista materializada para el "Master Sync".
116|   * Se debe llamar cada vez que una campaña sea aprobada o modificada.
117|   */
118|  async refreshActiveCampaignsView() {
119|    this.logger.log('🔄 Refrescando Materialized View (Master Sync)...');
120|    try {
121|      await this.$executeRawUnsafe('REFRESH MATERIALIZED VIEW CONCURRENTLY mv_active_campaigns;');
122|      this.logger.log('✅ mv_active_campaigns actualizada con éxito.');
123|    } catch (e) {
124|      if (e.message.includes('not been populated')) {
125|        // Fallback if not populated yet
126|        await this.$executeRawUnsafe('REFRESH MATERIALIZED VIEW mv_active_campaigns;');
127|      } else {
128|        this.logger.error(`❌ Error al refrescar vista: ${e.message}`);
129|      }
130|    }
131|  }
132|
133|  /**
134|   * Expose Prisma connectivity metrics for health monitoring.
135|   */
136|  async getHealthMetrics(): Promise<{ connected: boolean; activeConnections?: number }> {
137|    try {
138|      const result: any[] = await this.$queryRaw`
139|        SELECT count(*) as active_connections FROM pg_stat_activity WHERE datname = current_database()
140|      `;
141|      return {
142|        connected: true,
143|        activeConnections: Number(result[0]?.active_connections ?? 0),
144|      };
145|    } catch {
146|      return { connected: false };
147|    }
148|  }
